window.__PIONEER_REGISTER_TEST("TEST_HIST_SET_27", [
  {"q":"'धन के निष्कासन का सिद्धांत (Drain of Wealth) व आर्थिक राष्ट्रवाद' के ऐतिहासिक संदर्भ में 'निष्कासन के घटक' निम्नलिखित में से क्या है?","options":["ढाका के जुलाहों व भारतीय वस्त्र उद्योग का विनाश; प्रथम आधुनिक सूती मिल (1853/54 कावसजी नानाभाई डावर बंबई) व जूट मिल (1855 रिशरा बंगाल); टाटा स्टील TISCO (1907 साकची)","'होम चार्जेज' (Home Charges — लंदन इंडिया ऑफिस खर्च, ऋण ब्याज, ब्रिटिश अफसरों के वेतन-पेंशन, रेलवे गारंटी लाभ 5%, सैन्य खर्च)","कार्ताज-आर्मेडा-काफिला प्रणाली (समुद्री परमिट), भारत में पहला प्रिंटिंग प्रेस (गोवा, 1556), गोथिक स्थापत्य","डचों ने भारत से भारतीय वस्त्रों को (मसालों की बजाय इंडोनेशिया के बदले) मुख्य निर्यात वस्तु बनाया"],"correct":1,"explanation":"1896 के कलकत्ता कांग्रेस अधिवेशन ने आधिकारिक रूप से दादाभाई नौरोजी के धन निष्कासन सिद्धांत को स्वीकार करते हुए अकालों के लिए ब्रिटिश नीतियों को जिम्मेदार ठहराया।"},
  {"q":"[UPSC Prelims PYQ] 19वीं सदी के पूर्वार्द्ध में ब्रिटिश काल के दौरान औपनिवेशिक भारत में 'तिनकठिया प्रथा' से क्या तात्पर्य था?","options":["सरकारी बंजर भूमि पर 3/4 लगान का भुगतान","किसानों को अपनी भूमि के 3/20वें हिस्से पर अनिवार्य रूप से नील की खेती करना","सिंचाई नहरों पर तीन प्रकार के चुंगी कर","जमींदारों द्वारा तीन माह की अग्रिम कर वसूली"],"correct":1,"explanation":"बिहार के चंपारण में यूरोपीय नील बागान मालिकों (निलहों) ने किसानों को अपनी जमीन के 3/20वें हिस्से (प्रति बीघा 3 कट्ठा) पर नील उगाने हेतु बाध्य कर रखा था, जिसे 1917 में गांधीजी ने समाप्त कराया (UPSC CSE 2018 संदर्भ)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. पूर्व ब्रह्म समाजी शिव नारायण अग्निहोत्री ने 1887 में लाहौर में देव समाज की स्थापना की।\n2. अठारहवीं सदी में विश्व व्यापार के प्रमुख वस्त्र निर्यातक रहे भारत का 1813 के चार्टर एक्ट के बाद एकतरफा शुल्क-मुक्त नीति (ब्रिटिश माल पर नगण्य शुल्क, भारतीय माल पर भारी आयात शुल्क) से तेजी से अनौद्योगीकरण हुआ।\n3. प्रमुख संधियाँ एवं समझौते के अंतर्गत 'सुगौली की संधि (1816 ई.)' का ऐतिहासिक संबंध 'प्रथम आंग्ल-बर्मा युद्ध का अंत (असम, मणिपुर व अराकान-तेनासेरिम से बर्मा का दावा समाप्त)' से था।\n4. बिहार के जगदीशपुर के 80 वर्षीय जमींदार बाबू कुँवर सिंह ने अदम्य साहस से आजमगढ़-आरा में अंग्रेजी सेनाओं को परास्त किया और तात्या टोपे ने रामचंद्र पांडुरंग नाम से छापामार युद्ध लड़ा।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: 'सुगौली की संधि (1816 ई.)' का सही संबंध 'आंग्ल-नेपाल (गोरखा) युद्ध की समाप्ति (गढ़वाल, कुमाऊँ व तराई ब्रिटिश भारत को मिले)' से था — लॉर्ड हेस्टिंग्स के काल में 1814-16 के आंग्ल-नेपाल युद्ध का अंत मार्च 1816 की सुगौली संधि से हुआ।"},
  {"q":"[PSC/CDS युग्म पहचान — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. वॉरेन हेस्टिंग्स (1772-85) : 1872 की प्रथम जनगणना, राजकोट-अजमेर मेयो कॉलेज व वित्तीय विकेंद्रीकरण\n2. लॉर्ड मेयो (1869-72) : स्थानीय स्वशासन प्रस्ताव (1882), वर्नाक्युलर प्रेस एक्ट की समाप्ति व हंटर शिक्षा आयोग\n3. लॉर्ड डलहौजी (1848-56) : व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854)\n4. लॉर्ड रिपन (1880-84) : बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: लॉर्ड डलहौजी ने 1854 में डाकघर अधिनियम, भारतीय रेल (1853) व सिविल सेवा की खुली प्रतियोगिता लागू की। (अन्य सही युग्म: वॉरेन हेस्टिंग्स (1772-85)→द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त, लॉर्ड मेयो (1869-72)→1872 की प्रथम जनगणना, राजकोट-अजमेर मेयो कॉलेज व वित्तीय विकेंद्रीकरण, लॉर्ड रिपन (1880-84)→स्थानीय स्वशासन प्रस्ताव (1882), वर्नाक्युलर प्रेस एक्ट की समाप्ति व हंटर शिक्षा आयोग)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: अठारहवीं सदी में विश्व व्यापार के प्रमुख वस्त्र निर्यातक रहे भारत का 1813 के चार्टर एक्ट के बाद एकतरफा शुल्क-मुक्त नीति (ब्रिटिश माल पर नगण्य शुल्क, भारतीय माल पर भारी आयात शुल्क) से तेजी से अनौद्योगीकरण हुआ।\nकथन-2: प्लासी के युद्ध से पूर्व 1756 में कालकोठरी (Black Hole) घटना तथा फरवरी 1757 की 'अलीनगर की संधि' हुई थी।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) अठारहवीं सदी में विश्व व्यापार के प्रमुख वस्त्र निर्यातक रहे भारत का 1813 के चार्टर एक्ट के बाद एकतरफा शुल्क-मुक्त नीति (ब्रिटिश माल पर नगण्य शुल्क, भारतीय माल पर भारी आयात शुल्क) से तेजी से अनौद्योगीकरण हुआ। (2) प्लासी के युद्ध से पूर्व 1756 में कालकोठरी (Black Hole) घटना तथा फरवरी 1757 की 'अलीनगर की संधि' हुई थी।"},
  {"q":"1853 में प्रथम रेलवे (बंबई-ठाणे), विद्युत तार, डाक टिकट व लोक निर्माण विभाग (PWD) की स्थापना किसके काल में हुई?","options":["सती प्रथा निषेध (1829), ठगी दमन व अंग्रेजी शिक्षा पर मैकाले प्रस्ताव (1835)","बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना","द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त","व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854)"],"correct":3,"explanation":"लॉर्ड डलहौजी ने 1854 में डाकघर अधिनियम, भारतीय रेल (1853) व सिविल सेवा की खुली प्रतियोगिता लागू की। हिंदू विधवा पुनर्विवाह अधिनियम 1856 डलहौजी के काल में प्रस्तुत व लॉर्ड कैनिंग के काल में पारित हुआ।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. 1802 की बेसिन की संधि शिवाजी द्वितीय व रघुनाथराव ने चोल शासकों के साथ की थी जिससे मराठा साम्राज्य 50 वर्ष और अजेय रहा।\n2. 1809 की अमृतसर की संधि द्वारा रणजीत सिंह के राज्य की पूर्वी सीमा सतलज नदी निर्धारित हुई।\n3. विलियम बेंटिंक ने 1793 में भारत में प्रत्येक थाने पर 'दरोगा' की नियुक्ति कर कलेक्टर को असीमित न्यायिक व राजस्व दोनों शक्तियाँ सौंप दीं।\n4. 19वीं सदी का वहाबी आंदोलन मुख्यतः बंबई के पारसी व्यापारियों द्वारा अंग्रेजी शिक्षा के प्रचार हेतु चलाया गया था।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":1,"explanation":"कथन 2 सत्य है (1809 की अमृतसर की संधि द्वारा रणजीत सिंह के राज्य की पूर्वी सीमा सतलज नदी निर्धारित हुई।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"ऐतिहासिक संदर्भ में 'आर.पी. दत्त के 3 चरण: वाणिज्यिक पूंजीवाद (1757-1813), औद्योगिक मुक्त व्यापार (1813-1858 लंकाशायर कपड़ा डंपिंग), वित्तीय पूंजीवाद (1858 के बाद रेलवे-बैंक निवेश)' (आर्थिक रूपांतरण) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["औपनिवेशिक भारत में अनौद्योगीकरण, रेलवे व बागान उद्योग","धन के निष्कासन का सिद्धांत (Drain of Wealth) व आर्थिक राष्ट्रवाद","पुर्तगाली शक्ति का आगमन: वास्को डी गामा, अल्मीडा व अल्बुकर्क","डच, अंग्रेज एवं फ्रांसीसी व्यापारिक कंपनियों का स्थापना क्रम व युद्ध"],"correct":0,"explanation":"कार्ल मार्क्स ने कहा था कि ब्रिटिश हस्तक्षेपकारी सूती क्रांति ने भारतीय बुनकरों की हड्डियों से भारत के मैदान सफेद कर दिए और परंपरागत कृषि-उद्योग एकता तोड़ दी।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. औपनिवेशिक भारत में अनौद्योगीकरण, रेलवे व बागान उद्योग   B. डच, अंग्रेज एवं फ्रांसीसी व्यापारिक कंपनियों का स्थापना क्रम व युद्ध\nC. लॉर्ड वेलेजली की सहायक संधि (Subsidiary Alliance, 1798)   D. आधुनिक शिक्षा का विकास: मैकाले से सार्जेंट योजना तक\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["आधुनिक शिक्षा का विकास: मैकाले से सार्जेंट योजना तक","डच, अंग्रेज एवं फ्रांसीसी व्यापारिक कंपनियों का स्थापना क्रम व युद्ध","लॉर्ड वेलेजली की सहायक संधि (Subsidiary Alliance, 1798)","औपनिवेशिक भारत में अनौद्योगीकरण, रेलवे व बागान उद्योग"],"correct":3,"explanation":"डच, अंग्रेज एवं फ्रांसीसी व्यापारिक कंपनियों का स्थापना क्रम व युद्ध (1760 ई.), लॉर्ड वेलेजली की सहायक संधि (Subsidiary Alliance, 1798) (1798 ई.), आधुनिक शिक्षा का विकास: मैकाले से सार्जेंट योजना तक (1854 ई.), औपनिवेशिक भारत में अनौद्योगीकरण, रेलवे व बागान उद्योग (1907 ई.)। अतः सबसे अंत में औपनिवेशिक भारत में अनौद्योगीकरण, रेलवे व बागान उद्योग।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. कानपुर   B. रैयतवाड़ी एवं महालवाड़ी भू-राजस्व प्रणालियाँ\nC. अल-हिलाल (1912)   D. ज्योतिबा फुले (सत्यशोधक समाज), प्रार्थना समाज व दक्षिण सुधार\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["अल-हिलाल (1912)","रैयतवाड़ी एवं महालवाड़ी भू-राजस्व प्रणालियाँ","ज्योतिबा फुले (सत्यशोधक समाज), प्रार्थना समाज व दक्षिण सुधार","कानपुर"],"correct":1,"explanation":"रैयतवाड़ी एवं महालवाड़ी भू-राजस्व प्रणालियाँ (1820 ई.), कानपुर (1857 ई.), ज्योतिबा फुले (सत्यशोधक समाज), प्रार्थना समाज व दक्षिण सुधार (1873 ई.), अल-हिलाल (1912) (1912 ई.)। अतः सर्वप्रथम रैयतवाड़ी एवं महालवाड़ी भू-राजस्व प्रणालियाँ।"},
  {"q":"स्थायी बंदोबस्त (इस्तमरारी / जमींदारी व्यवस्था, 1793) — इसके संबंध में 'प्रमुख प्रावधान' कौन/क्या था?","options":["लॉर्ड कॉर्नवालिस (जॉन शोर योजना, जेम्स ग्रांट विरोध); बंगाल, बिहार, ओडिशा, बनारस व उत्तरी मद्रास (~19% क्षेत्र); जमींदार भू-स्वामी बने; राजस्व का 10/11 भाग कंपनी को व 1/11 जमींदार को","वास्को डी गामा (1498 कालीकट, जमोरिन द्वारा स्वागत); फ्रांसिस्को डी अल्मीडा ('ब्लू वाटर पॉलिसी'); अल्बुकर्क (वास्तविक संस्थापक, 1510 में बीजापुर से गोवा छीना, सती प्रथा पर रोक)","रैयतवाड़ी (थॉमस मुनरो व अलेक्जेंडर रीड — 1792 बारामहल प्रयोग, 1820 मद्रास/बंबई/असम, ~51% भूमि, सीधे किसान 'रैयत' से समझौता); महालवाड़ी (होल्ट मैकेंजी 1822 व मार्टिन बर्ड — गंगा घाटी/उ.प्र./पंजाब/मध्य प्रांत ~30% भूमि, पूरे ग्राम/'महाल' से समझौता)","अंग्रेज (सूरत अस्थायी 1611 मसूलीपट्टनम / स्थायी 1613 सूरत; फर्रुखसियर का 'मैग्नाकार्टा' फरमान 1717); डच (मसूलीपट्टनम 1605, 1759 बेदरा युद्ध में पराजित); फ्रांसीसी (सूरत 1668, पांडिचेरी 1674, 1760 वांडीवाश युद्ध में पराजित)"],"correct":0,"explanation":"स्थायी बंदोबस्त के कारण जमींदारों ने कृषि सुधार के बजाय शहरों में रहना (Absentee Landlordism) शुरू किया और 1859 व 1885 में बंगाल काश्तकारी अधिनियम लाने पड़े।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. ब्रिटिश भारत की विदेश एवं सीमांत नीति (घेरे की नीति व अग्रगामी नीति)   B. धन के निष्कासन का सिद्धांत (Drain of Wealth) व आर्थिक राष्ट्रवाद\nC. जनजातीय विद्रोह: खासी, चुआर, रामोसी, भील एवं कोया विद्रोह   D. अमृतसर की संधि (1809 ई.)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["धन के निष्कासन का सिद्धांत (Drain of Wealth) व आर्थिक राष्ट्रवाद","जनजातीय विद्रोह: खासी, चुआर, रामोसी, भील एवं कोया विद्रोह","ब्रिटिश भारत की विदेश एवं सीमांत नीति (घेरे की नीति व अग्रगामी नीति)","अमृतसर की संधि (1809 ई.)"],"correct":3,"explanation":"अमृतसर की संधि (1809 ई.) (1809 ई.), जनजातीय विद्रोह: खासी, चुआर, रामोसी, भील एवं कोया विद्रोह (1829 ई.), ब्रिटिश भारत की विदेश एवं सीमांत नीति (घेरे की नीति व अग्रगामी नीति) (1839-42 ई.), धन के निष्कासन का सिद्धांत (Drain of Wealth) व आर्थिक राष्ट्रवाद (1867 ई.)। अतः सर्वप्रथम अमृतसर की संधि (1809 ई.)।"},
  {"q":"'स्थायी बंदोबस्त (इस्तमरारी / जमींदारी व्यवस्था, 1793)' के ऐतिहासिक संदर्भ में 'सूर्यास्त कानून व दोष' निम्नलिखित में से क्या है?","options":["कार्ताज-आर्मेडा-काफिला प्रणाली (समुद्री परमिट), भारत में पहला प्रिंटिंग प्रेस (गोवा, 1556), गोथिक स्थापत्य","'सूर्यास्त कानून' (Sunset Law) के तहत तय तिथि के सूर्यास्त तक भुगतान न होने पर जमींदारी नीलाम; किसानों का भयंकर शोषण व अनुपस्थित जमींदारी","रैयतवाड़ी में लगान बहुत ऊँचा (~50% तक) व समय-समय पर पुनरीक्षित; तीनों व्यवस्थाओं ने भूमि को क्रय-विक्रय की वस्तु बनाकर ऋणग्रस्तता बढ़ाई","डचों ने भारत से भारतीय वस्त्रों को (मसालों की बजाय इंडोनेशिया के बदले) मुख्य निर्यात वस्तु बनाया"],"correct":1,"explanation":"स्थायी बंदोबस्त के कारण जमींदारों ने कृषि सुधार के बजाय शहरों में रहना (Absentee Landlordism) शुरू किया और 1859 व 1885 में बंगाल काश्तकारी अधिनियम लाने पड़े।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: स्थायी बंदोबस्त लॉर्ड डलहौजी द्वारा 1820 ई. में मद्रास और बंबई प्रेसीडेंसी के 51% ब्रिटिश भारतीय क्षेत्र में लागू किया गया था।\nकथन-2: बाल गंगाधर तिलक ने ब्रिटिश सरकार के हस्तक्षेप के विरोध स्वरूप 1891 के 'सहमति आयु अधिनियम' (Age of Consent Act — कन्या विवाह न्यूनतम आयु 10 से 12 वर्ष) की आलोचना की थी।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है (स्थायी बंदोबस्त 1793 में लॉर्ड कॉर्नवालिस ने मुख्यतः बंगाल-बिहार-ओडिशा (~19% ब्रिटिश भूमि) में लागू किया था; मद्रास-बंबई (51%) में रैयतवाड़ी लागू हुई।)। कथन-2 सत्य है (बाल गंगाधर तिलक ने ब्रिटिश सरकार के हस्तक्षेप के विरोध स्वरूप 1891 के 'सहमति आयु अधिनियम' (Age of Consent Act — कन्या विवाह न्यूनतम आयु 10 से 12 वर्ष) की आलोचना की थी।)।"},
  {"q":"[UPSC / CDS कालानुक्रम] निम्नलिखित ऐतिहासिक घटनाओं का प्राचीनतम से नवीनतम सही कालानुक्रम क्या है?\n1. धन के निष्कासन का सिद्धांत (Drain of Wealth) व आर्थिक राष्ट्रवाद   2. द बंगाली (The Bengalee)\n3. प्लासी का युद्ध (1757) एवं ब्लैक होल त्रासदी   4. मंगलौर की संधि (1784 ई.)","options":["प्लासी का युद्ध (1757) एवं ब्लैक होल त्रासदी → मंगलौर की संधि (1784 ई.) → द बंगाली (The Bengalee) → धन के निष्कासन का सिद्धांत (Drain of Wealth) व आर्थिक राष्ट्रवाद","प्लासी का युद्ध (1757) एवं ब्लैक होल त्रासदी → धन के निष्कासन का सिद्धांत (Drain of Wealth) व आर्थिक राष्ट्रवाद → मंगलौर की संधि (1784 ई.) → द बंगाली (The Bengalee)","प्लासी का युद्ध (1757) एवं ब्लैक होल त्रासदी → मंगलौर की संधि (1784 ई.) → धन के निष्कासन का सिद्धांत (Drain of Wealth) व आर्थिक राष्ट्रवाद → द बंगाली (The Bengalee)","मंगलौर की संधि (1784 ई.) → प्लासी का युद्ध (1757) एवं ब्लैक होल त्रासदी → धन के निष्कासन का सिद्धांत (Drain of Wealth) व आर्थिक राष्ट्रवाद → द बंगाली (The Bengalee)"],"correct":2,"explanation":"सही कालानुक्रम: प्लासी का युद्ध (1757) एवं ब्लैक होल त्रासदी (1757 ई.), मंगलौर की संधि (1784 ई.) (1784 ई.), धन के निष्कासन का सिद्धांत (Drain of Wealth) व आर्थिक राष्ट्रवाद (1867 ई.), द बंगाली (The Bengalee) (1879 ई.)"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: प्रमुख संधियाँ एवं समझौते के अंतर्गत 'सुगौली की संधि (1816 ई.)' का ऐतिहासिक संबंध 'प्रथम आंग्ल-बर्मा युद्ध का अंत (असम, मणिपुर व अराकान-तेनासेरिम से बर्मा का दावा समाप्त)' से था।\nकथन-2: संवैधानिक अधिनियम एवं प्रावधान के अंतर्गत 'रेगुलेटिंग एक्ट, 1773' का ऐतिहासिक संबंध 'कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'सुगौली की संधि (1816 ई.)' का सही संबंध 'आंग्ल-नेपाल (गोरखा) युद्ध की समाप्ति (गढ़वाल, कुमाऊँ व तराई ब्रिटिश भारत को मिले)' से था — लॉर्ड हेस्टिंग्स के काल में 1814-16 के आंग्ल-नेपाल युद्ध का अंत मार्च 1816 की सुगौली संधि से हुआ। (2) 'रेगुलेटिंग एक्ट, 1773' का सही संबंध 'गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ' से था — 1773 के रेगुलेटिंग एक्ट से वॉरेन हेस्टिंग्स बंगाल के प्रथम गवर्नर-जनरल बने व बंबई-मद्रास उनके अधीन हुए।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 1809 की अमृतसर की संधि द्वारा रणजीत सिंह के राज्य की पूर्वी सीमा सतलज नदी निर्धारित हुई।\nकथन-2: व्यपगत सिद्धांत (विलय वर्ष) के अंतर्गत 'जैतपुर व संबलपुर विलय' का ऐतिहासिक संबंध '1853 ई.' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (1809 की अमृतसर की संधि द्वारा रणजीत सिंह के राज्य की पूर्वी सीमा सतलज नदी निर्धारित हुई।)। कथन-2 गलत है — 'जैतपुर व संबलपुर विलय' का सही संबंध '1849 ई.' से था — बुंदेलखंड के जैतपुर और ओडिशा के संबलपुर का 1849 ई. में व्यपगत सिद्धांत से विलय हुआ।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — प्रमुख संधियाँ एवं समझौते] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. सुगौली की संधि (1816 ई.) : ईस्ट इंडिया कंपनी को बंगाल, बिहार और उड़ीसा की दीवानी अधिकार प्राप्ति\n2. सालबाई की संधि (1782 ई.) : प्रथम आंग्ल-मराठा युद्ध की समाप्ति (माधवराव नारायण को पेशवा स्वीकृति)\n3. गांधी-इरविन समझौता (1931 ई.) : सविनय अवज्ञा आंदोलन का स्थगन और कांग्रेस की द्वितीय गोलमेज सम्मेलन में भागीदारी\n4. मंगलौर की संधि (1784 ई.) : द्वितीय आंग्ल-मैसूर युद्ध का अंत (टीपू सुल्तान व लॉर्ड मैकार्टनी के बीच)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":0,"explanation":"युग्म 1 गलत है: 'सुगौली की संधि (1816 ई.)' का सही संबंध 'आंग्ल-नेपाल (गोरखा) युद्ध की समाप्ति (गढ़वाल, कुमाऊँ व तराई ब्रिटिश भारत को मिले)' से है (न कि 'ईस्ट इंडिया कंपनी को बंगाल, बिहार और उड़ीसा की दीवानी अधिकार प्राप्ति' से)। लॉर्ड हेस्टिंग्स के काल में 1814-16 के आंग्ल-नेपाल युद्ध का अंत मार्च 1816 की सुगौली संधि से हुआ।"},
  {"q":"[UPSC / CDS कालानुक्रम] निम्नलिखित ऐतिहासिक घटनाओं का प्राचीनतम से नवीनतम सही कालानुक्रम क्या है?\n1. अलीगढ़, देवबंद, पारसी, सिख सुधार व सामाजिक कानून (1829–1930)   2. मंगलौर की संधि (1784 ई.)\n3. झाँसी विलय (गंगाधर राव मृत्यु बाद)   4. संन्यासी विद्रोह, पाइक विद्रोह, कोल विद्रोह एवं संथाल हूल (1855-56)","options":["मंगलौर की संधि (1784 ई.) → झाँसी विलय (गंगाधर राव मृत्यु बाद) → अलीगढ़, देवबंद, पारसी, सिख सुधार व सामाजिक कानून (1829–1930) → संन्यासी विद्रोह, पाइक विद्रोह, कोल विद्रोह एवं संथाल हूल (1855-56)","झाँसी विलय (गंगाधर राव मृत्यु बाद) → मंगलौर की संधि (1784 ई.) → संन्यासी विद्रोह, पाइक विद्रोह, कोल विद्रोह एवं संथाल हूल (1855-56) → अलीगढ़, देवबंद, पारसी, सिख सुधार व सामाजिक कानून (1829–1930)","मंगलौर की संधि (1784 ई.) → झाँसी विलय (गंगाधर राव मृत्यु बाद) → संन्यासी विद्रोह, पाइक विद्रोह, कोल विद्रोह एवं संथाल हूल (1855-56) → अलीगढ़, देवबंद, पारसी, सिख सुधार व सामाजिक कानून (1829–1930)","मंगलौर की संधि (1784 ई.) → संन्यासी विद्रोह, पाइक विद्रोह, कोल विद्रोह एवं संथाल हूल (1855-56) → झाँसी विलय (गंगाधर राव मृत्यु बाद) → अलीगढ़, देवबंद, पारसी, सिख सुधार व सामाजिक कानून (1829–1930)"],"correct":2,"explanation":"सही कालानुक्रम: मंगलौर की संधि (1784 ई.) (1784 ई.), झाँसी विलय (गंगाधर राव मृत्यु बाद) (1853 ई.), संन्यासी विद्रोह, पाइक विद्रोह, कोल विद्रोह एवं संथाल हूल (1855-56) (1855-56 ई.), अलीगढ़, देवबंद, पारसी, सिख सुधार व सामाजिक कानून (1829–1930) (1891 ई.)"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. प्रमुख संधियाँ एवं समझौते के अंतर्गत 'यांडबू की संधि (1826 ई.)' का ऐतिहासिक संबंध 'महाराजा रणजीत सिंह और लॉर्ड मिंटो प्रथम (चार्ल्स मेटकाफ) — सतलज नदी सीमा तय' से था।\n2. कलकत्ता नगर की स्थापना फ्रांसीसी गवर्नर फ्रांस्वा मार्टिन ने 1674 में तीन गाँवों को मिलाकर की थी।\n3. सुधार संगठन एवं संस्थापक के अंतर्गत 'सर्वेंट्स ऑफ इंडिया सोसाइटी (1905)' का ऐतिहासिक संबंध 'शिव नारायण अग्निहोत्री' से था।\n4. महालवाड़ी व्यवस्था का व्यावहारिक रूप से उत्तर भारत में व्यवस्थित कार्यान्वयन 1833 में लॉर्ड विलियम बेंटिंक के समय मार्टिन बर्ड ('उत्तर भारत में भू-राजस्व का जनक') व जेम्स थॉमसन ने किया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (महालवाड़ी व्यवस्था का व्यावहारिक रूप से उत्तर भारत में व्यवस्थित कार्यान्वयन 1833 में लॉर्ड विलियम बेंटिंक के समय मार्टिन बर्ड ('उत्तर भारत में भू-राजस्व का जनक') व जेम्स थॉमसन ने किया।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: सुधार संगठन एवं संस्थापक के अंतर्गत 'रामकृष्ण मिशन (1897)' का ऐतिहासिक संबंध 'गोपाल कृष्ण गोखले' से था।\nकथन-2: विलियम बेंटिंक ने 1793 में भारत में प्रत्येक थाने पर 'दरोगा' की नियुक्ति कर कलेक्टर को असीमित न्यायिक व राजस्व दोनों शक्तियाँ सौंप दीं।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'रामकृष्ण मिशन (1897)' का सही संबंध 'स्वामी विवेकानंद' से था — स्वामी विवेकानंद ने अपने गुरु रामकृष्ण परमहंस की शिक्षाओं व मानव सेवा हेतु रामकृष्ण मिशन की नींव रखी। (2) थाने व दरोगा आधारित पुलिस प्रणाली तथा कलेक्टर से न्यायिक शक्ति अलग करना (शक्ति पृथक्करण) 1793 के 'कॉर्नवालिस कोड' की मुख्य विशेषता थी।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. राजा राममोहन राय ने 'सत्यार्थ प्रकाश' पुस्तक लिखकर 'वेदों की ओर लौटो' का नारा देते हुए 1875 में ब्रह्म समाज की स्थापना की थी।\n2. स्थायी बंदोबस्त में राज्य की माँग स्थायी रूप से तय कर दी गई थी, किंतु जमींदारों और रैयतों (किसानों) के बीच लगान की कोई अधिकतम सीमा तय नहीं थी, जिससे 'पट्टनीदार' मध्यस्थ बढ़े।\n3. व्यपगत सिद्धांत (विलय वर्ष) के अंतर्गत 'सतारा विलय (डलहौजी)' का ऐतिहासिक संबंध '1849 ई.' से था।\n4. सुधार संगठन एवं संस्थापक के अंतर्गत 'ब्रह्म समाज (1828)' का ऐतिहासिक संबंध 'देवेंद्रनाथ टैगोर' से था।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":1,"explanation":"कथन 2 सत्य है (स्थायी बंदोबस्त में राज्य की माँग स्थायी रूप से तय कर दी गई थी, किंतु जमींदारों और रैयतों (किसानों) के बीच लगान की कोई अधिकतम सीमा तय नहीं थी, जिससे 'पट्टनीदार' मध्यस्थ बढ़े।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — प्रमुख संधियाँ एवं समझौते] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. इलाहाबाद की संधियाँ (1765 ई.) : ईस्ट इंडिया कंपनी को बंगाल, बिहार और उड़ीसा की दीवानी अधिकार प्राप्ति\n2. सुगौली की संधि (1816 ई.) : आंग्ल-नेपाल (गोरखा) युद्ध की समाप्ति (गढ़वाल, कुमाऊँ व तराई ब्रिटिश भारत को मिले)\n3. यांडबू की संधि (1826 ई.) : दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147)\n4. मद्रास की संधि (1769 ई.) : प्रथम आंग्ल-मैसूर युद्ध की समाप्ति (विजित क्षेत्रों की वापसी व पारस्परिक रक्षा समझौता)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: 'यांडबू की संधि (1826 ई.)' का सही संबंध 'प्रथम आंग्ल-बर्मा युद्ध का अंत (असम, मणिपुर व अराकान-तेनासेरिम से बर्मा का दावा समाप्त)' से है (न कि 'दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147)' से)। लॉर्ड एमहर्स्ट के शासन में 1824-26 का प्रथम आंग्ल-बर्मा युद्ध 1826 की यांडबू संधि से समाप्त हुआ।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: लॉर्ड हेस्टिंग्स के काल में 1814-16 के आंग्ल-नेपाल युद्ध का अंत मार्च 1816 की सुगौली संधि से हुआ।\nकथन-2: दादाभाई नौरोजी ने भारत की प्रति व्यक्ति वार्षिक आय मात्र 20 रुपये आंकलित करते हुए सिद्ध किया कि भारत की गरीबी प्राकृतिक नहीं बल्कि ब्रिटिश आर्थिक निष्कासन ('अनिष्टों का अनिष्ट') का परिणाम है।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) लॉर्ड हेस्टिंग्स के काल में 1814-16 के आंग्ल-नेपाल युद्ध का अंत मार्च 1816 की सुगौली संधि से हुआ। (2) दादाभाई नौरोजी ने भारत की प्रति व्यक्ति वार्षिक आय मात्र 20 रुपये आंकलित करते हुए सिद्ध किया कि भारत की गरीबी प्राकृतिक नहीं बल्कि ब्रिटिश आर्थिक निष्कासन ('अनिष्टों का अनिष्ट') का परिणाम है।"},
  {"q":"ऐतिहासिक संदर्भ में 'दादाभाई नौरोजी ('पॉवर्टी एंड अन-ब्रिटिश रूल इन इंडिया', 1867 ईस्ट इंडिया एसोसिएशन पत्र 'इंग्लैंड्स डेट टू इंडिया'); आर.सी. दत्त ('इकोनॉमिक हिस्ट्री ऑफ इंडिया'); एम.जी. रानाडे, जी.वी. जोशी, जी. सुब्रमण्यम अय्यर' (प्रमुख सिद्धांतकार व पुस्तकें) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["धन के निष्कासन का सिद्धांत (Drain of Wealth) व आर्थिक राष्ट्रवाद","औपनिवेशिक भारत में अनौद्योगीकरण, रेलवे व बागान उद्योग","पुर्तगाली शक्ति का आगमन: वास्को डी गामा, अल्मीडा व अल्बुकर्क","डच, अंग्रेज एवं फ्रांसीसी व्यापारिक कंपनियों का स्थापना क्रम व युद्ध"],"correct":0,"explanation":"1896 के कलकत्ता कांग्रेस अधिवेशन ने आधिकारिक रूप से दादाभाई नौरोजी के धन निष्कासन सिद्धांत को स्वीकार करते हुए अकालों के लिए ब्रिटिश नीतियों को जिम्मेदार ठहराया।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. भारत में रेल निर्माण के लिए ब्रिटिश निजी कंपनियों को सरकारी गारंटी पर 0% ब्याज और संपूर्ण पूंजी केवल भारतीय किसानों के स्वैच्छिक शेयर से जुटाई गई थी।\n2. यूरोप के ऑस्ट्रिया उत्तराधिकार युद्ध की समाप्ति पर हुई एक्स-ला-शैपल संधि (1748) से प्रथम कर्नाटक युद्ध रुका।\n3. 1854 के वुड घोषणापत्र की सिफारिश पर 1857 में कलकत्ता, बंबई व मद्रास विश्वविद्यालय खुले।\n4. स्वामी दयानंद सरस्वती ने 1875 ई. में बंबई में आर्य समाज की स्थापना की; उन्होंने वेदों को अपौरुषेय मानकर बाल विवाह, सती, छुआछूत व जन्म आधारित जातिवाद का खंडन किया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":0,"explanation":"कथन 1 असत्य है। सुधार: भारतीय रेलवे का निर्माण 'गारंटीड इंटरेस्ट सिस्टम' (ब्रिटिश निवेशकों को भारतीय करदाताओं के धन से 5% सुनिश्चित न्यूनतम लाभ की गारंटी) पर हुआ था।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: सुधार संगठन एवं संस्थापक के अंतर्गत 'ब्रह्म समाज (1828)' का ऐतिहासिक संबंध 'देवेंद्रनाथ टैगोर' से था।\nकथन-2: 1857 क्रांति केंद्र एवं नेता के अंतर्गत 'फैजाबाद' का ऐतिहासिक संबंध 'खान बहादुर खाँ' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'ब्रह्म समाज (1828)' का सही संबंध 'राजा राममोहन राय' से था — राजा राममोहन राय ने एकेश्वरवाद के प्रचार व सती-मूर्तिपूजा विरोध हेतु ब्रह्म समाज बनाया। (2) 'फैजाबाद' का सही संबंध 'मौलवी अहमदुल्ला शाह' से था — मौलवी अहमदुल्ला 1857 के सबसे कट्टर ब्रिटिश-विरोधी नेता थे जिन पर 50,000 रु. का इनाम था।"},
  {"q":"[UPSC Prelims पैटर्न — प्रमुख संधियाँ एवं समझौते] निम्नलिखित युग्मों पर विचार कीजिए:\n1. सुगौली की संधि (1816 ई.) : आंग्ल-नेपाल (गोरखा) युद्ध की समाप्ति (गढ़वाल, कुमाऊँ व तराई ब्रिटिश भारत को मिले)\n2. पेरिस की संधि (1763 ई.) : तृतीय आंग्ल-फ्रांसीसी कर्नाटक युद्ध की समाप्ति व भारत में फ्रांसीसी राजनीतिक शक्ति का अंत\n3. पूना समझौता / पूना पैक्ट (1932 ई.) : दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (लॉर्ड हेस्टिंग्स के काल में 1814-16 के आंग्ल-नेपाल युद्ध का अंत मार्च 1816 की सुगौली संधि से हुआ।) युग्म 2 सही (1763 की पेरिस संधि से फ्रांसीसियों को केवल व्यापारिक बस्तियाँ (पांडिचेरी, चंद्रनगर) मिलीं, किलेबंदी समाप्त हुई।) युग्म 3 सही (मदन मोहन मालवीय व राजेंद्र प्रसाद के प्रयासों से गांधीजी की ओर से हस्ताक्षर व डॉ. आंबेडकर के बीच पूना पैक्ट हुआ।)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. चार्टर अधिनियम, 1833   B. हिंदू पैट्रियट (नील विद्रोह समर्थक)\nC. सुगौली की संधि (1816 ई.)   D. सर्वेंट्स ऑफ इंडिया सोसाइटी (1905)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["हिंदू पैट्रियट (नील विद्रोह समर्थक)","सुगौली की संधि (1816 ई.)","चार्टर अधिनियम, 1833","सर्वेंट्स ऑफ इंडिया सोसाइटी (1905)"],"correct":1,"explanation":"सुगौली की संधि (1816 ई.) (1816 ई.), चार्टर अधिनियम, 1833 (1833 ई.), हिंदू पैट्रियट (नील विद्रोह समर्थक) (1859 ई.), सर्वेंट्स ऑफ इंडिया सोसाइटी (1905) (1905 ई.)। अतः सर्वप्रथम सुगौली की संधि (1816 ई.)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: गवर्नर-जनरल / वायसराय एवं कार्य के अंतर्गत 'लॉर्ड डलहौजी (1848-56)' का ऐतिहासिक संबंध '1858 में क्राउन शासन की घोषणा, व्यपगत नीति वापसी एवं 1861 का उच्च न्यायालय अधिनियम' से था।\nकथन-2: पत्र-पत्रिकाएँ एवं संपादक के अंतर्गत 'उदंत मार्तंड (1826, प्रथम हिंदी पत्र)' का ऐतिहासिक संबंध 'शिशिर कुमार घोष एवं मोतीलाल घोष' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'लॉर्ड डलहौजी (1848-56)' का सही संबंध 'व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854)' से था — लॉर्ड डलहौजी ने 1854 में डाकघर अधिनियम, भारतीय रेल (1853) व सिविल सेवा की खुली प्रतियोगिता लागू की। (2) 'उदंत मार्तंड (1826, प्रथम हिंदी पत्र)' का सही संबंध 'पं. जुगल किशोर शुक्ल' से था — कानपुर निवासी जुगल किशोर शुक्ल ने 30 मई 1826 को कलकत्ता से प्रथम हिंदी साप्ताहिक निकाला।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: स्वामी दयानंद सरस्वती (मूलशंकर) ने वेदों की ओर लौटने के आह्वान सहित आर्य समाज स्थापित किया।\nकथन-2: पत्र-पत्रिकाएँ एवं संपादक के अंतर्गत 'बंगाल गजट (1780)' का ऐतिहासिक संबंध 'पं. जुगल किशोर शुक्ल' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (स्वामी दयानंद सरस्वती (मूलशंकर) ने वेदों की ओर लौटने के आह्वान सहित आर्य समाज स्थापित किया।)। कथन-2 गलत है — 'बंगाल गजट (1780)' का सही संबंध 'जेम्स ऑगस्टस हिक्की' से था — जेम्स ऑगस्टस हिक्की ने 1780 में कलकत्ता से भारत का पहला मुद्रित अंग्रेजी साप्ताहिक शुरू किया।"},
  {"q":"रैयतवाड़ी एवं महालवाड़ी भू-राजस्व प्रणालियाँ — इसके संबंध में 'मुख्य अंतर व प्रवर्तक' कौन/क्या था?","options":["वास्को डी गामा (1498 कालीकट, जमोरिन द्वारा स्वागत); फ्रांसिस्को डी अल्मीडा ('ब्लू वाटर पॉलिसी'); अल्बुकर्क (वास्तविक संस्थापक, 1510 में बीजापुर से गोवा छीना, सती प्रथा पर रोक)","रैयतवाड़ी (थॉमस मुनरो व अलेक्जेंडर रीड — 1792 बारामहल प्रयोग, 1820 मद्रास/बंबई/असम, ~51% भूमि, सीधे किसान 'रैयत' से समझौता); महालवाड़ी (होल्ट मैकेंजी 1822 व मार्टिन बर्ड — गंगा घाटी/उ.प्र./पंजाब/मध्य प्रांत ~30% भूमि, पूरे ग्राम/'महाल' से समझौता)","अंग्रेज (सूरत अस्थायी 1611 मसूलीपट्टनम / स्थायी 1613 सूरत; फर्रुखसियर का 'मैग्नाकार्टा' फरमान 1717); डच (मसूलीपट्टनम 1605, 1759 बेदरा युद्ध में पराजित); फ्रांसीसी (सूरत 1668, पांडिचेरी 1674, 1760 वांडीवाश युद्ध में पराजित)","लॉर्ड कॉर्नवालिस (जॉन शोर योजना, जेम्स ग्रांट विरोध); बंगाल, बिहार, ओडिशा, बनारस व उत्तरी मद्रास (~19% क्षेत्र); जमींदार भू-स्वामी बने; राजस्व का 10/11 भाग कंपनी को व 1/11 जमींदार को"],"correct":1,"explanation":"भारत में ब्रिटिश भू-राजस्व व्यवस्थाओं में रैयतवाड़ी सर्वाधिक भूभाग (~51%), महालवाड़ी (~30%) और स्थायी बंदोबस्त (~19%) क्षेत्रफल पर लागू थीं।"},
  {"q":"[UPSC Prelims पैटर्न — प्रमुख संधियाँ एवं समझौते] निम्नलिखित युग्मों पर विचार कीजिए:\n1. सुगौली की संधि (1816 ई.) : प्रथम आंग्ल-बर्मा युद्ध का अंत (असम, मणिपुर व अराकान-तेनासेरिम से बर्मा का दावा समाप्त)\n2. यांडबू की संधि (1826 ई.) : प्रथम आंग्ल-फ्रांसीसी कर्नाटक युद्ध का अंत व मद्रास की अंग्रेजों को वापसी\n3. एक्स-ला-शैपल की संधि (1748 ई.) : दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: सुगौली की संधि (1816 ई.) — आंग्ल-नेपाल (गोरखा) युद्ध की समाप्ति (गढ़वाल, कुमाऊँ व तराई ब्रिटिश भारत को मिले))। युग्म 2 गलत (सही: यांडबू की संधि (1826 ई.) — प्रथम आंग्ल-बर्मा युद्ध का अंत (असम, मणिपुर व अराकान-तेनासेरिम से बर्मा का दावा समाप्त))। युग्म 3 गलत (सही: एक्स-ला-शैपल की संधि (1748 ई.) — प्रथम आंग्ल-फ्रांसीसी कर्नाटक युद्ध का अंत व मद्रास की अंग्रेजों को वापसी)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. पत्र-पत्रिकाएँ एवं संपादक के अंतर्गत 'केसरी एवं मराठा (1881)' का ऐतिहासिक संबंध 'मौलाना अबुल कलाम आजाद' से था।\n2. सुधार संगठन एवं संस्थापक के अंतर्गत 'प्रार्थना समाज (1867)' का ऐतिहासिक संबंध 'स्वामी दयानंद सरस्वती' से था।\n3. धन के निष्कासन सिद्धांत के अंतर्गत दादाभाई नौरोजी ने ब्रिटिश रेलवे गारंटी प्रणाली और मुक्त व्यापार को भारत के औद्योगीकरण का सबसे बड़ा वरदान बताया।\n4. लॉर्ड एमहर्स्ट के शासन में 1824-26 का प्रथम आंग्ल-बर्मा युद्ध 1826 की यांडबू संधि से समाप्त हुआ।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (लॉर्ड एमहर्स्ट के शासन में 1824-26 का प्रथम आंग्ल-बर्मा युद्ध 1826 की यांडबू संधि से समाप्त हुआ।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[UPSC Prelims पैटर्न — प्रमुख संधियाँ एवं समझौते] निम्नलिखित युग्मों पर विचार कीजिए:\n1. यांडबू की संधि (1826 ई.) : प्रथम आंग्ल-बर्मा युद्ध का अंत (असम, मणिपुर व अराकान-तेनासेरिम से बर्मा का दावा समाप्त)\n2. सुगौली की संधि (1816 ई.) : सविनय अवज्ञा आंदोलन का स्थगन और कांग्रेस की द्वितीय गोलमेज सम्मेलन में भागीदारी\n3. गांधी-इरविन समझौता (1931 ई.) : ईस्ट इंडिया कंपनी को बंगाल, बिहार और उड़ीसा की दीवानी अधिकार प्राप्ति\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (लॉर्ड एमहर्स्ट के शासन में 1824-26 का प्रथम आंग्ल-बर्मा युद्ध 1826 की यांडबू संधि से समाप्त हुआ।) युग्म 2 गलत (सही: सुगौली की संधि (1816 ई.) — आंग्ल-नेपाल (गोरखा) युद्ध की समाप्ति (गढ़वाल, कुमाऊँ व तराई ब्रिटिश भारत को मिले))। युग्म 3 गलत (सही: गांधी-इरविन समझौता (1931 ई.) — सविनय अवज्ञा आंदोलन का स्थगन और कांग्रेस की द्वितीय गोलमेज सम्मेलन में भागीदारी)।"},
  {"q":"औपनिवेशिक भारत में अनौद्योगीकरण, रेलवे व बागान उद्योग — इसके संबंध में 'आर्थिक रूपांतरण' कौन/क्या था?","options":["दादाभाई नौरोजी ('पॉवर्टी एंड अन-ब्रिटिश रूल इन इंडिया', 1867 ईस्ट इंडिया एसोसिएशन पत्र 'इंग्लैंड्स डेट टू इंडिया'); आर.सी. दत्त ('इकोनॉमिक हिस्ट्री ऑफ इंडिया'); एम.जी. रानाडे, जी.वी. जोशी, जी. सुब्रमण्यम अय्यर","अंग्रेज (सूरत अस्थायी 1611 मसूलीपट्टनम / स्थायी 1613 सूरत; फर्रुखसियर का 'मैग्नाकार्टा' फरमान 1717); डच (मसूलीपट्टनम 1605, 1759 बेदरा युद्ध में पराजित); फ्रांसीसी (सूरत 1668, पांडिचेरी 1674, 1760 वांडीवाश युद्ध में पराजित)","आर.पी. दत्त के 3 चरण: वाणिज्यिक पूंजीवाद (1757-1813), औद्योगिक मुक्त व्यापार (1813-1858 लंकाशायर कपड़ा डंपिंग), वित्तीय पूंजीवाद (1858 के बाद रेलवे-बैंक निवेश)","वास्को डी गामा (1498 कालीकट, जमोरिन द्वारा स्वागत); फ्रांसिस्को डी अल्मीडा ('ब्लू वाटर पॉलिसी'); अल्बुकर्क (वास्तविक संस्थापक, 1510 में बीजापुर से गोवा छीना, सती प्रथा पर रोक)"],"correct":2,"explanation":"कार्ल मार्क्स ने कहा था कि ब्रिटिश हस्तक्षेपकारी सूती क्रांति ने भारतीय बुनकरों की हड्डियों से भारत के मैदान सफेद कर दिए और परंपरागत कृषि-उद्योग एकता तोड़ दी।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. राजा राममोहन राय ने एकेश्वरवाद के प्रचार व सती-मूर्तिपूजा विरोध हेतु ब्रह्म समाज बनाया।\n2. 1773 के रेगुलेटिंग एक्ट की कमियों (सुप्रीम कोर्ट व गवर्नर-जनरल के अधिकार क्षेत्र विवाद) को दूर करने के लिए 1781 का 'एक्ट ऑफ सेटलमेंट' पारित किया गया।\n3. धन के निष्कासन सिद्धांत के अंतर्गत दादाभाई नौरोजी ने ब्रिटिश रेलवे गारंटी प्रणाली और मुक्त व्यापार को भारत के औद्योगीकरण का सबसे बड़ा वरदान बताया।\n4. ज्योतिबा फुले ने ब्राह्मणवादी पुरोहितवाद के बिना विवाह ('सत्यशोधक विवाह') और दलितों-महिलाओं के लिए 1848 में पुणे में भारत का प्रथम बालिका विद्यालय शुरू किया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: नौरोजी, दत्त व तिलक जैसे आर्थिक राष्ट्रवादियों ने स्पष्ट किया कि भारत में रेलवे गारंटी प्रणाली, अनिर्यात योग्य 'होम चार्जेज' व एकतरफा मुक्त व्यापार ने भारतीय हस्तशिल्प (अनौद्योगीकरण) को नष्ट किया।"},
  {"q":"[UPSC Prelims पैटर्न — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित युग्मों पर विचार कीजिए:\n1. लॉर्ड डलहौजी (1848-56) : व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854)\n2. लॉर्ड लिनलिथगो (1936-44) : प्रांतीय चुनाव (1937), द्वितीय विश्व युद्ध प्रवेश (1939), अगस्त प्रस्ताव (1940) व क्रिप्स मिशन\n3. लॉर्ड मेयो (1869-72) : स्थानीय स्वशासन प्रस्ताव (1882), वर्नाक्युलर प्रेस एक्ट की समाप्ति व हंटर शिक्षा आयोग\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (लॉर्ड डलहौजी ने 1854 में डाकघर अधिनियम, भारतीय रेल (1853) व सिविल सेवा की खुली प्रतियोगिता लागू की।) युग्म 2 सही (लॉर्ड लिनलिथगो ब्रिटिश भारत में सबसे लंबे समय (1936-1944) तक रहने वाले वायसराय थे।) युग्म 3 गलत (सही: लॉर्ड मेयो (1869-72) — 1872 की प्रथम जनगणना, राजकोट-अजमेर मेयो कॉलेज व वित्तीय विकेंद्रीकरण)।"},
  {"q":"[UPSC Prelims पैटर्न — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित युग्मों पर विचार कीजिए:\n1. लॉर्ड डलहौजी (1848-56) : व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854)\n2. लॉर्ड कर्जन (1899-1905) : 1872 की प्रथम जनगणना, राजकोट-अजमेर मेयो कॉलेज व वित्तीय विकेंद्रीकरण\n3. लॉर्ड मेयो (1869-72) : 1858 में क्राउन शासन की घोषणा, व्यपगत नीति वापसी एवं 1861 का उच्च न्यायालय अधिनियम\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (लॉर्ड डलहौजी ने 1854 में डाकघर अधिनियम, भारतीय रेल (1853) व सिविल सेवा की खुली प्रतियोगिता लागू की।) युग्म 2 गलत (सही: लॉर्ड कर्जन (1899-1905) — बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन)। युग्म 3 गलत (सही: लॉर्ड मेयो (1869-72) — 1872 की प्रथम जनगणना, राजकोट-अजमेर मेयो कॉलेज व वित्तीय विकेंद्रीकरण)।"},
  {"q":"'औपनिवेशिक भारत में अनौद्योगीकरण, रेलवे व बागान उद्योग' के ऐतिहासिक संदर्भ में 'औद्योगिक प्रभाव' निम्नलिखित में से क्या है?","options":["डचों ने भारत से भारतीय वस्त्रों को (मसालों की बजाय इंडोनेशिया के बदले) मुख्य निर्यात वस्तु बनाया","ढाका के जुलाहों व भारतीय वस्त्र उद्योग का विनाश; प्रथम आधुनिक सूती मिल (1853/54 कावसजी नानाभाई डावर बंबई) व जूट मिल (1855 रिशरा बंगाल); टाटा स्टील TISCO (1907 साकची)","कार्ताज-आर्मेडा-काफिला प्रणाली (समुद्री परमिट), भारत में पहला प्रिंटिंग प्रेस (गोवा, 1556), गोथिक स्थापत्य","'होम चार्जेज' (Home Charges — लंदन इंडिया ऑफिस खर्च, ऋण ब्याज, ब्रिटिश अफसरों के वेतन-पेंशन, रेलवे गारंटी लाभ 5%, सैन्य खर्च)"],"correct":1,"explanation":"कार्ल मार्क्स ने कहा था कि ब्रिटिश हस्तक्षेपकारी सूती क्रांति ने भारतीय बुनकरों की हड्डियों से भारत के मैदान सफेद कर दिए और परंपरागत कृषि-उद्योग एकता तोड़ दी।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. 1717 के शाही फरमान द्वारा मिले 'दस्तक' पास का कंपनी के कर्मचारियों द्वारा निजी व्यापार में भारी दुरुपयोग ही बंगाल के नवाबों (सिराजुद्दौला व मीर कासिम) से संघर्ष का मूल कारण बना।\n2. गोपाल कृष्ण गोखले ने निस्वार्थ देशसेवकों के प्रशिक्षण हेतु 1905 में यह संस्था बनाई।\n3. प्रमुख संधियाँ एवं समझौते के अंतर्गत 'बसीन की संधि (1802 ई.)' का ऐतिहासिक संबंध 'आंग्ल-नेपाल (गोरखा) युद्ध की समाप्ति (गढ़वाल, कुमाऊँ व तराई ब्रिटिश भारत को मिले)' से था।\n4. 1858 के भारत शासन अधिनियम व महारानी की घोषणा के अंतर्गत 'व्यपगत सिद्धांत' समाप्त किया गया, देसी रियासतों के विलय पर रोक लगी और वायसराय पद बना (प्रथम: लॉर्ड कैनिंग)।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: 'बसीन की संधि (1802 ई.)' का सही संबंध 'पेशवा बाजीराव द्वितीय द्वारा अंग्रेजों की सहायक संधि स्वीकार करना' से था — 1802 की बसीन संधि के अंतर्गत पेशवा बाजीराव द्वितीय ने कंपनी की सहायक सेना व पूना में ब्रिटिश संरक्षण स्वीकार किया।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. SNDP योगम (1903)   B. रैयतवाड़ी एवं महालवाड़ी भू-राजस्व प्रणालियाँ\nC. लखनऊ (अवध)   D. चार्ल्स मेटकाफ (1835-36)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["रैयतवाड़ी एवं महालवाड़ी भू-राजस्व प्रणालियाँ","लखनऊ (अवध)","SNDP योगम (1903)","चार्ल्स मेटकाफ (1835-36)"],"correct":0,"explanation":"रैयतवाड़ी एवं महालवाड़ी भू-राजस्व प्रणालियाँ (1820 ई.), चार्ल्स मेटकाफ (1835-36) (1835 ई.), लखनऊ (अवध) (1857 ई.), SNDP योगम (1903) (1903 ई.)। अतः सर्वप्रथम रैयतवाड़ी एवं महालवाड़ी भू-राजस्व प्रणालियाँ।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. केसरी एवं मराठा (1881)   B. झाँसी विलय (गंगाधर राव मृत्यु बाद)\nC. वुड्स डिस्पैच (1854 ई.)   D. अमृतसर की संधि (1809 ई.)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["झाँसी विलय (गंगाधर राव मृत्यु बाद)","वुड्स डिस्पैच (1854 ई.)","केसरी एवं मराठा (1881)","अमृतसर की संधि (1809 ई.)"],"correct":3,"explanation":"अमृतसर की संधि (1809 ई.) (1809 ई.), झाँसी विलय (गंगाधर राव मृत्यु बाद) (1853 ई.), वुड्स डिस्पैच (1854 ई.) (1854 ई.), केसरी एवं मराठा (1881) (1881 ई.)। अतः सर्वप्रथम अमृतसर की संधि (1809 ई.)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — गवर्नर-जनरल / वायसराय एवं कार्य] सूची-I को सूची-II से सुमेलित कीजिए:\nA. लॉर्ड डलहौजी (1848-56)   |   1. वर्नाक्युलर प्रेस एक्ट (1878), सिविल सेवा आयु 21 से 19 वर्ष करना व रॉयल टाइटल्स एक्ट\nB. लॉर्ड कैनिंग (1856-62)   |   2. व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854)\nC. लॉर्ड लिटन (1876-80)   |   3. बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना\nD. लॉर्ड कॉर्नवालिस (1786-93)   |   4. 1858 में क्राउन शासन की घोषणा, व्यपगत नीति वापसी एवं 1861 का उच्च न्यायालय अधिनियम","options":["A-2, B-1, C-4, D-3","A-2, B-4, C-1, D-3","A-2, B-4, C-3, D-1","A-4, B-2, C-1, D-3"],"correct":1,"explanation":"सही सुमेलन: लॉर्ड डलहौजी (1848-56) (व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854)), लॉर्ड कैनिंग (1856-62) (1858 में क्राउन शासन की घोषणा, व्यपगत नीति वापसी एवं 1861 का उच्च न्यायालय अधिनियम), लॉर्ड लिटन (1876-80) (वर्नाक्युलर प्रेस एक्ट (1878), सिविल सेवा आयु 21 से 19 वर्ष करना व रॉयल टाइटल्स एक्ट), लॉर्ड कॉर्नवालिस (1786-93) (बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना)।"},
  {"q":"'रैयतवाड़ी एवं महालवाड़ी भू-राजस्व प्रणालियाँ' के ऐतिहासिक संदर्भ में 'राजस्व प्रभाव' निम्नलिखित में से क्या है?","options":["कार्ताज-आर्मेडा-काफिला प्रणाली (समुद्री परमिट), भारत में पहला प्रिंटिंग प्रेस (गोवा, 1556), गोथिक स्थापत्य","'सूर्यास्त कानून' (Sunset Law) के तहत तय तिथि के सूर्यास्त तक भुगतान न होने पर जमींदारी नीलाम; किसानों का भयंकर शोषण व अनुपस्थित जमींदारी","रैयतवाड़ी में लगान बहुत ऊँचा (~50% तक) व समय-समय पर पुनरीक्षित; तीनों व्यवस्थाओं ने भूमि को क्रय-विक्रय की वस्तु बनाकर ऋणग्रस्तता बढ़ाई","डचों ने भारत से भारतीय वस्त्रों को (मसालों की बजाय इंडोनेशिया के बदले) मुख्य निर्यात वस्तु बनाया"],"correct":2,"explanation":"भारत में ब्रिटिश भू-राजस्व व्यवस्थाओं में रैयतवाड़ी सर्वाधिक भूभाग (~51%), महालवाड़ी (~30%) और स्थायी बंदोबस्त (~19%) क्षेत्रफल पर लागू थीं।"},
  {"q":"1816 ई. की 'सुगौली की संधि' किन दो शक्तियों के बीच युद्ध समाप्त करने हेतु हुई थी?","options":["आंग्ल-नेपाल (गोरखा) युद्ध की समाप्ति (गढ़वाल, कुमाऊँ व तराई ब्रिटिश भारत को मिले)","ईस्ट इंडिया कंपनी को बंगाल, बिहार और उड़ीसा की दीवानी अधिकार प्राप्ति","तृतीय आंग्ल-फ्रांसीसी कर्नाटक युद्ध की समाप्ति व भारत में फ्रांसीसी राजनीतिक शक्ति का अंत","प्रथम आंग्ल-फ्रांसीसी कर्नाटक युद्ध का अंत व मद्रास की अंग्रेजों को वापसी"],"correct":0,"explanation":"लॉर्ड हेस्टिंग्स के काल में 1814-16 के आंग्ल-नेपाल युद्ध का अंत मार्च 1816 की सुगौली संधि से हुआ। इस संधि के पश्चात नेपाल के काठमांडू में ब्रिटिश रेजिडेंट रखा गया।"},
  {"q":"[UPSC/PCS सूची सुमेलन — प्रमुख संधियाँ एवं समझौते] सूची-I को सूची-II से सुमेलित कीजिए:\nA. यांडबू की संधि (1826 ई.)   |   1. प्रथम आंग्ल-फ्रांसीसी कर्नाटक युद्ध का अंत व मद्रास की अंग्रेजों को वापसी\nB. एक्स-ला-शैपल की संधि (1748 ई.)   |   2. दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147)\nC. मंगलौर की संधि (1784 ई.)   |   3. प्रथम आंग्ल-बर्मा युद्ध का अंत (असम, मणिपुर व अराकान-तेनासेरिम से बर्मा का दावा समाप्त)\nD. पूना समझौता / पूना पैक्ट (1932 ई.)   |   4. द्वितीय आंग्ल-मैसूर युद्ध का अंत (टीपू सुल्तान व लॉर्ड मैकार्टनी के बीच)","options":["A-1, B-3, C-4, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-2, D-4","A-3, B-1, C-4, D-2"],"correct":3,"explanation":"सही सुमेलन: यांडबू की संधि (1826 ई.) (प्रथम आंग्ल-बर्मा युद्ध का अंत (असम, मणिपुर व अराकान-तेनासेरिम से बर्मा का दावा समाप्त)), एक्स-ला-शैपल की संधि (1748 ई.) (प्रथम आंग्ल-फ्रांसीसी कर्नाटक युद्ध का अंत व मद्रास की अंग्रेजों को वापसी), मंगलौर की संधि (1784 ई.) (द्वितीय आंग्ल-मैसूर युद्ध का अंत (टीपू सुल्तान व लॉर्ड मैकार्टनी के बीच)), पूना समझौता / पूना पैक्ट (1932 ई.) (दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147))।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: वर्नाक्यूलर प्रेस एक्ट (1878) लॉर्ड रिपन द्वारा लागू किया गया था तथा लॉर्ड लिटन ने 1882 में इसे समाप्त कर प्रेस को पूर्ण स्वतंत्रता दी।\nकथन-2: स्वामी विवेकानंद ने अपने गुरु रामकृष्ण परमहंस की शिक्षाओं व मानव सेवा हेतु रामकृष्ण मिशन की नींव रखी।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है (वर्नाक्यूलर प्रेस एक्ट 1878 लॉर्ड लिटन ने देशी भाषा के अखबारों के दमन हेतु लगाया था, जबकि उदारवादी वायसराय लॉर्ड रिपन ने 1882 में इसे रद्द किया।)। कथन-2 सत्य है (स्वामी विवेकानंद ने अपने गुरु रामकृष्ण परमहंस की शिक्षाओं व मानव सेवा हेतु रामकृष्ण मिशन की नींव रखी।)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. 1802 की बसीन संधि के अंतर्गत पेशवा बाजीराव द्वितीय ने कंपनी की सहायक सेना व पूना में ब्रिटिश संरक्षण स्वीकार किया।\n2. बाल गंगाधर तिलक ने ब्रिटिश सरकार के हस्तक्षेप के विरोध स्वरूप 1891 के 'सहमति आयु अधिनियम' (Age of Consent Act — कन्या विवाह न्यूनतम आयु 10 से 12 वर्ष) की आलोचना की थी।\n3. रैयतवाड़ी व्यवस्था में कंपनी सरकार सीधे किसानों से कोई संपर्क नहीं रखती थी और संपूर्ण गाँव के मुखिया 'जमींदार' को स्थायी भू-स्वामी मानती थी।\n4. हरिश्चंद्र मुखर्जी ने 'हिंदू पैट्रियट' में बंगाल के नील बागान मालिकों के अत्याचारों का भंडाफोड़ किया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: रैयतवाड़ी में बीच में कोई जमींदार नहीं था—सीधे प्रत्येक 'रैयत' (किसान) को पट्टा दिया जाता था, हालांकि ऊँचे कर के कारण महाजनों का चंगुल बढ़ा।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — प्रमुख संधियाँ एवं समझौते] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. मद्रास की संधि (1769 ई.) : प्रथम आंग्ल-मैसूर युद्ध की समाप्ति (विजित क्षेत्रों की वापसी व पारस्परिक रक्षा समझौता)\n2. पूना समझौता / पूना पैक्ट (1932 ई.) : दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147)\n3. बसीन की संधि (1802 ई.) : महाराजा रणजीत सिंह और लॉर्ड मिंटो प्रथम (चार्ल्स मेटकाफ) — सतलज नदी सीमा तय\n4. यांडबू की संधि (1826 ई.) : प्रथम आंग्ल-बर्मा युद्ध का अंत (असम, मणिपुर व अराकान-तेनासेरिम से बर्मा का दावा समाप्त)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: 'बसीन की संधि (1802 ई.)' का सही संबंध 'पेशवा बाजीराव द्वितीय द्वारा अंग्रेजों की सहायक संधि स्वीकार करना' से है (न कि 'महाराजा रणजीत सिंह और लॉर्ड मिंटो प्रथम (चार्ल्स मेटकाफ) — सतलज नदी सीमा तय' से)। 1802 की बसीन संधि के अंतर्गत पेशवा बाजीराव द्वितीय ने कंपनी की सहायक सेना व पूना में ब्रिटिश संरक्षण स्वीकार किया।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: लॉर्ड हेस्टिंग्स के काल में 1814-16 के आंग्ल-नेपाल युद्ध का अंत मार्च 1816 की सुगौली संधि से हुआ।\nकथन-2: राजा राममोहन राय ने एकेश्वरवाद, मूर्तिपूजा विरोध, प्रेस स्वतंत्रता व आधुनिक पाश्चात्य वैज्ञानिक शिक्षा का समर्थन किया तथा डेविड हेयर के साथ 1817 में हिंदू कॉलेज की स्थापना में मदद की।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) लॉर्ड हेस्टिंग्स के काल में 1814-16 के आंग्ल-नेपाल युद्ध का अंत मार्च 1816 की सुगौली संधि से हुआ। (2) राजा राममोहन राय ने एकेश्वरवाद, मूर्तिपूजा विरोध, प्रेस स्वतंत्रता व आधुनिक पाश्चात्य वैज्ञानिक शिक्षा का समर्थन किया तथा डेविड हेयर के साथ 1817 में हिंदू कॉलेज की स्थापना में मदद की।"},
  {"q":"25 अप्रैल 1809 की 'अमृतसर की संधि' किन दो पक्षों के बीच हुई थी?","options":["तृतीय आंग्ल-फ्रांसीसी कर्नाटक युद्ध की समाप्ति व भारत में फ्रांसीसी राजनीतिक शक्ति का अंत","महाराजा रणजीत सिंह और लॉर्ड मिंटो प्रथम (चार्ल्स मेटकाफ) — सतलज नदी सीमा तय","प्रथम आंग्ल-फ्रांसीसी कर्नाटक युद्ध का अंत व मद्रास की अंग्रेजों को वापसी","ईस्ट इंडिया कंपनी को बंगाल, बिहार और उड़ीसा की दीवानी अधिकार प्राप्ति"],"correct":1,"explanation":"1809 की अमृतसर की संधि द्वारा रणजीत सिंह के राज्य की पूर्वी सीमा सतलज नदी निर्धारित हुई। इससे मालवा के सिख राज्यों पर अंग्रेजों का संरक्षण स्थापित हुआ और रणजीत सिंह का विस्तार पश्चिम की ओर हुआ।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. जनजातीय-किसान विद्रोह एवं नेतृत्व के अंतर्गत 'कोल विद्रोह (1831-32)' का ऐतिहासिक संबंध 'अल्लूरी सीताराम राजू' से था।\n2. दादाभाई नौरोजी ने भारत की प्रति व्यक्ति वार्षिक आय मात्र 20 रुपये आंकलित करते हुए सिद्ध किया कि भारत की गरीबी प्राकृतिक नहीं बल्कि ब्रिटिश आर्थिक निष्कासन ('अनिष्टों का अनिष्ट') का परिणाम है।\n3. प्रमुख संधियाँ एवं समझौते के अंतर्गत 'मंगलौर की संधि (1784 ई.)' का ऐतिहासिक संबंध 'प्रथम आंग्ल-मराठा युद्ध की समाप्ति (माधवराव नारायण को पेशवा स्वीकृति)' से था।\n4. जनजातीय-किसान विद्रोह एवं नेतृत्व के अंतर्गत 'पाइक विद्रोह (ओडिशा, 1817)' का ऐतिहासिक संबंध 'बुद्धो भगत (सिंदराय व बिंद्राय सहयोगी)' से था।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":1,"explanation":"कथन 2 सत्य है (दादाभाई नौरोजी ने भारत की प्रति व्यक्ति वार्षिक आय मात्र 20 रुपये आंकलित करते हुए सिद्ध किया कि भारत की गरीबी प्राकृतिक नहीं बल्कि ब्रिटिश आर्थिक निष्कासन ('अनिष्टों का अनिष्ट') का परिणाम है।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. 1857 में लखनऊ विद्रोह का नेतृत्व कुँवर सिंह ने किया और कानपुर में विद्रोह को जनरल ह्यूरोज ने दबाया था।\n2. जनजातीय-किसान विद्रोह एवं नेतृत्व के अंतर्गत 'रम्पा विद्रोह (1922-24)' का ऐतिहासिक संबंध 'जतरा भगत (जतरा उराँव)' से था।\n3. व्यपगत सिद्धांत के अंतर्गत लॉर्ड डलहौजी द्वारा ब्रिटिश साम्राज्य में विलय किया गया सबसे पहला राज्य अवध (1848) था।\n4. अठारहवीं सदी में विश्व व्यापार के प्रमुख वस्त्र निर्यातक रहे भारत का 1813 के चार्टर एक्ट के बाद एकतरफा शुल्क-मुक्त नीति (ब्रिटिश माल पर नगण्य शुल्क, भारतीय माल पर भारी आयात शुल्क) से तेजी से अनौद्योगीकरण हुआ।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (अठारहवीं सदी में विश्व व्यापार के प्रमुख वस्त्र निर्यातक रहे भारत का 1813 के चार्टर एक्ट के बाद एकतरफा शुल्क-मुक्त नीति (ब्रिटिश माल पर नगण्य शुल्क, भारतीय माल पर भारी आयात शुल्क) से तेजी से अनौद्योगीकरण हुआ।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"धन के निष्कासन का सिद्धांत (Drain of Wealth) व आर्थिक राष्ट्रवाद — इसके संबंध में 'प्रमुख सिद्धांतकार व पुस्तकें' कौन/क्या था?","options":["दादाभाई नौरोजी ('पॉवर्टी एंड अन-ब्रिटिश रूल इन इंडिया', 1867 ईस्ट इंडिया एसोसिएशन पत्र 'इंग्लैंड्स डेट टू इंडिया'); आर.सी. दत्त ('इकोनॉमिक हिस्ट्री ऑफ इंडिया'); एम.जी. रानाडे, जी.वी. जोशी, जी. सुब्रमण्यम अय्यर","आर.पी. दत्त के 3 चरण: वाणिज्यिक पूंजीवाद (1757-1813), औद्योगिक मुक्त व्यापार (1813-1858 लंकाशायर कपड़ा डंपिंग), वित्तीय पूंजीवाद (1858 के बाद रेलवे-बैंक निवेश)","वास्को डी गामा (1498 कालीकट, जमोरिन द्वारा स्वागत); फ्रांसिस्को डी अल्मीडा ('ब्लू वाटर पॉलिसी'); अल्बुकर्क (वास्तविक संस्थापक, 1510 में बीजापुर से गोवा छीना, सती प्रथा पर रोक)","अंग्रेज (सूरत अस्थायी 1611 मसूलीपट्टनम / स्थायी 1613 सूरत; फर्रुखसियर का 'मैग्नाकार्टा' फरमान 1717); डच (मसूलीपट्टनम 1605, 1759 बेदरा युद्ध में पराजित); फ्रांसीसी (सूरत 1668, पांडिचेरी 1674, 1760 वांडीवाश युद्ध में पराजित)"],"correct":0,"explanation":"1896 के कलकत्ता कांग्रेस अधिवेशन ने आधिकारिक रूप से दादाभाई नौरोजी के धन निष्कासन सिद्धांत को स्वीकार करते हुए अकालों के लिए ब्रिटिश नीतियों को जिम्मेदार ठहराया।"},
  {"q":"[PSC/CDS युग्म पहचान — प्रमुख संधियाँ एवं समझौते] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. एक्स-ला-शैपल की संधि (1748 ई.) : प्रथम आंग्ल-बर्मा युद्ध का अंत (असम, मणिपुर व अराकान-तेनासेरिम से बर्मा का दावा समाप्त)\n2. सुगौली की संधि (1816 ई.) : आंग्ल-नेपाल (गोरखा) युद्ध की समाप्ति (गढ़वाल, कुमाऊँ व तराई ब्रिटिश भारत को मिले)\n3. यांडबू की संधि (1826 ई.) : प्रथम आंग्ल-मैसूर युद्ध की समाप्ति (विजित क्षेत्रों की वापसी व पारस्परिक रक्षा समझौता)\n4. मद्रास की संधि (1769 ई.) : तृतीय आंग्ल-फ्रांसीसी कर्नाटक युद्ध की समाप्ति व भारत में फ्रांसीसी राजनीतिक शक्ति का अंत","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":1,"explanation":"केवल युग्म 2 सही है: लॉर्ड हेस्टिंग्स के काल में 1814-16 के आंग्ल-नेपाल युद्ध का अंत मार्च 1816 की सुगौली संधि से हुआ। (अन्य सही युग्म: एक्स-ला-शैपल की संधि (1748 ई.)→प्रथम आंग्ल-फ्रांसीसी कर्नाटक युद्ध का अंत व मद्रास की अंग्रेजों को वापसी, यांडबू की संधि (1826 ई.)→प्रथम आंग्ल-बर्मा युद्ध का अंत (असम, मणिपुर व अराकान-तेनासेरिम से बर्मा का दावा समाप्त), मद्रास की संधि (1769 ई.)→प्रथम आंग्ल-मैसूर युद्ध की समाप्ति (विजित क्षेत्रों की वापसी व पारस्परिक रक्षा समझौता))।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: प्रमुख संधियाँ एवं समझौते के अंतर्गत 'बसीन की संधि (1802 ई.)' का ऐतिहासिक संबंध 'आंग्ल-नेपाल (गोरखा) युद्ध की समाप्ति (गढ़वाल, कुमाऊँ व तराई ब्रिटिश भारत को मिले)' से था।\nकथन-2: स्थायी बंदोबस्त में राज्य की माँग स्थायी रूप से तय कर दी गई थी, किंतु जमींदारों और रैयतों (किसानों) के बीच लगान की कोई अधिकतम सीमा तय नहीं थी, जिससे 'पट्टनीदार' मध्यस्थ बढ़े।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है ('बसीन की संधि (1802 ई.)' का सही संबंध 'पेशवा बाजीराव द्वितीय द्वारा अंग्रेजों की सहायक संधि स्वीकार करना' से था — 1802 की बसीन संधि के अंतर्गत पेशवा बाजीराव द्वितीय ने कंपनी की सहायक सेना व पूना में ब्रिटिश संरक्षण स्वीकार किया।)। कथन-2 सत्य है (स्थायी बंदोबस्त में राज्य की माँग स्थायी रूप से तय कर दी गई थी, किंतु जमींदारों और रैयतों (किसानों) के बीच लगान की कोई अधिकतम सीमा तय नहीं थी, जिससे 'पट्टनीदार' मध्यस्थ बढ़े।)।"},
  {"q":"[PSC/CDS युग्म पहचान — प्रमुख संधियाँ एवं समझौते] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. एक्स-ला-शैपल की संधि (1748 ई.) : तृतीय आंग्ल-फ्रांसीसी कर्नाटक युद्ध की समाप्ति व भारत में फ्रांसीसी राजनीतिक शक्ति का अंत\n2. पेरिस की संधि (1763 ई.) : पेशवा बाजीराव द्वितीय द्वारा अंग्रेजों की सहायक संधि स्वीकार करना\n3. यांडबू की संधि (1826 ई.) : प्रथम आंग्ल-बर्मा युद्ध का अंत (असम, मणिपुर व अराकान-तेनासेरिम से बर्मा का दावा समाप्त)\n4. बसीन की संधि (1802 ई.) : प्रथम आंग्ल-मराठा युद्ध की समाप्ति (माधवराव नारायण को पेशवा स्वीकृति)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: लॉर्ड एमहर्स्ट के शासन में 1824-26 का प्रथम आंग्ल-बर्मा युद्ध 1826 की यांडबू संधि से समाप्त हुआ। (अन्य सही युग्म: एक्स-ला-शैपल की संधि (1748 ई.)→प्रथम आंग्ल-फ्रांसीसी कर्नाटक युद्ध का अंत व मद्रास की अंग्रेजों को वापसी, पेरिस की संधि (1763 ई.)→तृतीय आंग्ल-फ्रांसीसी कर्नाटक युद्ध की समाप्ति व भारत में फ्रांसीसी राजनीतिक शक्ति का अंत, बसीन की संधि (1802 ई.)→पेशवा बाजीराव द्वितीय द्वारा अंग्रेजों की सहायक संधि स्वीकार करना)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. प्रमुख संधियाँ एवं समझौते के अंतर्गत 'अमृतसर की संधि (1809 ई.)' का ऐतिहासिक संबंध 'सविनय अवज्ञा आंदोलन का स्थगन और कांग्रेस की द्वितीय गोलमेज सम्मेलन में भागीदारी' से था।\n2. स्वामी विवेकानंद ने अपने गुरु रामकृष्ण परमहंस की शिक्षाओं व मानव सेवा हेतु रामकृष्ण मिशन की नींव रखी।\n3. लॉर्ड हेस्टिंग्स के काल में 1814-16 के आंग्ल-नेपाल युद्ध का अंत मार्च 1816 की सुगौली संधि से हुआ।\n4. पूर्व ब्रह्म समाजी शिव नारायण अग्निहोत्री ने 1887 में लाहौर में देव समाज की स्थापना की।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":0,"explanation":"कथन 1 असत्य है। सुधार: 'अमृतसर की संधि (1809 ई.)' का सही संबंध 'महाराजा रणजीत सिंह और लॉर्ड मिंटो प्रथम (चार्ल्स मेटकाफ) — सतलज नदी सीमा तय' से था — 1809 की अमृतसर की संधि द्वारा रणजीत सिंह के राज्य की पूर्वी सीमा सतलज नदी निर्धारित हुई।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. स्थायी बंदोबस्त (इस्तमरारी / जमींदारी व्यवस्था, 1793)   B. अमृत बाजार पत्रिका (1868)\nC. चार्टर अधिनियम, 1833   D. बसीन की संधि (1802 ई.)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["अमृत बाजार पत्रिका (1868)","बसीन की संधि (1802 ई.)","चार्टर अधिनियम, 1833","स्थायी बंदोबस्त (इस्तमरारी / जमींदारी व्यवस्था, 1793)"],"correct":3,"explanation":"स्थायी बंदोबस्त (इस्तमरारी / जमींदारी व्यवस्था, 1793) (1793 ई.), बसीन की संधि (1802 ई.) (1802 ई.), चार्टर अधिनियम, 1833 (1833 ई.), अमृत बाजार पत्रिका (1868) (1868 ई.)। अतः सर्वप्रथम स्थायी बंदोबस्त (इस्तमरारी / जमींदारी व्यवस्था, 1793)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 1809 की अमृतसर की संधि द्वारा रणजीत सिंह के राज्य की पूर्वी सीमा सतलज नदी निर्धारित हुई।\nकथन-2: प्रमुख संधियाँ एवं समझौते के अंतर्गत 'बसीन की संधि (1802 ई.)' का ऐतिहासिक संबंध 'आंग्ल-नेपाल (गोरखा) युद्ध की समाप्ति (गढ़वाल, कुमाऊँ व तराई ब्रिटिश भारत को मिले)' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (1809 की अमृतसर की संधि द्वारा रणजीत सिंह के राज्य की पूर्वी सीमा सतलज नदी निर्धारित हुई।)। कथन-2 गलत है — 'बसीन की संधि (1802 ई.)' का सही संबंध 'पेशवा बाजीराव द्वितीय द्वारा अंग्रेजों की सहायक संधि स्वीकार करना' से था — 1802 की बसीन संधि के अंतर्गत पेशवा बाजीराव द्वितीय ने कंपनी की सहायक सेना व पूना में ब्रिटिश संरक्षण स्वीकार किया।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. लॉर्ड विलियम बेंटिंक (1828-35)   B. लॉर्ड वेलेजली की सहायक संधि (Subsidiary Alliance, 1798)\nC. हिंदू पैट्रियट (नील विद्रोह समर्थक)   D. स्थायी बंदोबस्त (इस्तमरारी / जमींदारी व्यवस्था, 1793)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["हिंदू पैट्रियट (नील विद्रोह समर्थक)","लॉर्ड वेलेजली की सहायक संधि (Subsidiary Alliance, 1798)","लॉर्ड विलियम बेंटिंक (1828-35)","स्थायी बंदोबस्त (इस्तमरारी / जमींदारी व्यवस्था, 1793)"],"correct":3,"explanation":"स्थायी बंदोबस्त (इस्तमरारी / जमींदारी व्यवस्था, 1793) (1793 ई.), लॉर्ड वेलेजली की सहायक संधि (Subsidiary Alliance, 1798) (1798 ई.), लॉर्ड विलियम बेंटिंक (1828-35) (1829 ई.), हिंदू पैट्रियट (नील विद्रोह समर्थक) (1859 ई.)। अतः सर्वप्रथम स्थायी बंदोबस्त (इस्तमरारी / जमींदारी व्यवस्था, 1793)।"},
  {"q":"ऐतिहासिक संदर्भ में 'लॉर्ड कॉर्नवालिस (जॉन शोर योजना, जेम्स ग्रांट विरोध); बंगाल, बिहार, ओडिशा, बनारस व उत्तरी मद्रास (~19% क्षेत्र); जमींदार भू-स्वामी बने; राजस्व का 10/11 भाग कंपनी को व 1/11 जमींदार को' (प्रमुख प्रावधान) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["स्थायी बंदोबस्त (इस्तमरारी / जमींदारी व्यवस्था, 1793)","पुर्तगाली शक्ति का आगमन: वास्को डी गामा, अल्मीडा व अल्बुकर्क","डच, अंग्रेज एवं फ्रांसीसी व्यापारिक कंपनियों का स्थापना क्रम व युद्ध","रैयतवाड़ी एवं महालवाड़ी भू-राजस्व प्रणालियाँ"],"correct":0,"explanation":"स्थायी बंदोबस्त के कारण जमींदारों ने कृषि सुधार के बजाय शहरों में रहना (Absentee Landlordism) शुरू किया और 1859 व 1885 में बंगाल काश्तकारी अधिनियम लाने पड़े।"},
  {"q":"ऐतिहासिक संदर्भ में 'रैयतवाड़ी (थॉमस मुनरो व अलेक्जेंडर रीड — 1792 बारामहल प्रयोग, 1820 मद्रास/बंबई/असम, ~51% भूमि, सीधे किसान 'रैयत' से समझौता); महालवाड़ी (होल्ट मैकेंजी 1822 व मार्टिन बर्ड — गंगा घाटी/उ.प्र./पंजाब/मध्य प्रांत ~30% भूमि, पूरे ग्राम/'महाल' से समझौता)' (मुख्य अंतर व प्रवर्तक) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["डच, अंग्रेज एवं फ्रांसीसी व्यापारिक कंपनियों का स्थापना क्रम व युद्ध","पुर्तगाली शक्ति का आगमन: वास्को डी गामा, अल्मीडा व अल्बुकर्क","स्थायी बंदोबस्त (इस्तमरारी / जमींदारी व्यवस्था, 1793)","रैयतवाड़ी एवं महालवाड़ी भू-राजस्व प्रणालियाँ"],"correct":3,"explanation":"भारत में ब्रिटिश भू-राजस्व व्यवस्थाओं में रैयतवाड़ी सर्वाधिक भूभाग (~51%), महालवाड़ी (~30%) और स्थायी बंदोबस्त (~19%) क्षेत्रफल पर लागू थीं।"},
  {"q":"[UPSC Prelims पैटर्न — प्रमुख संधियाँ एवं समझौते] निम्नलिखित युग्मों पर विचार कीजिए:\n1. सुगौली की संधि (1816 ई.) : प्रथम आंग्ल-मराठा युद्ध की समाप्ति (माधवराव नारायण को पेशवा स्वीकृति)\n2. सालबाई की संधि (1782 ई.) : प्रथम आंग्ल-मैसूर युद्ध की समाप्ति (विजित क्षेत्रों की वापसी व पारस्परिक रक्षा समझौता)\n3. मद्रास की संधि (1769 ई.) : तृतीय आंग्ल-फ्रांसीसी कर्नाटक युद्ध की समाप्ति व भारत में फ्रांसीसी राजनीतिक शक्ति का अंत\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: सुगौली की संधि (1816 ई.) — आंग्ल-नेपाल (गोरखा) युद्ध की समाप्ति (गढ़वाल, कुमाऊँ व तराई ब्रिटिश भारत को मिले))। युग्म 2 गलत (सही: सालबाई की संधि (1782 ई.) — प्रथम आंग्ल-मराठा युद्ध की समाप्ति (माधवराव नारायण को पेशवा स्वीकृति))। युग्म 3 गलत (सही: मद्रास की संधि (1769 ई.) — प्रथम आंग्ल-मैसूर युद्ध की समाप्ति (विजित क्षेत्रों की वापसी व पारस्परिक रक्षा समझौता))।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: भारत में रेल निर्माण के लिए ब्रिटिश निजी कंपनियों को सरकारी गारंटी पर 0% ब्याज और संपूर्ण पूंजी केवल भारतीय किसानों के स्वैच्छिक शेयर से जुटाई गई थी।\nकथन-2: प्रमुख संधियाँ एवं समझौते के अंतर्गत 'मंगलौर की संधि (1784 ई.)' का ऐतिहासिक संबंध 'प्रथम आंग्ल-मराठा युद्ध की समाप्ति (माधवराव नारायण को पेशवा स्वीकृति)' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) भारतीय रेलवे का निर्माण 'गारंटीड इंटरेस्ट सिस्टम' (ब्रिटिश निवेशकों को भारतीय करदाताओं के धन से 5% सुनिश्चित न्यूनतम लाभ की गारंटी) पर हुआ था। (2) 'मंगलौर की संधि (1784 ई.)' का सही संबंध 'द्वितीय आंग्ल-मैसूर युद्ध का अंत (टीपू सुल्तान व लॉर्ड मैकार्टनी के बीच)' से था — मार्च 1784 की मंगलौर की संधि पर गवर्नर-जनरल वॉरेन हेस्टिंग्स ने कहा था: 'यह मैकार्टनी का पागलपन है'!"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: रैयतवाड़ी व्यवस्था में कंपनी सरकार सीधे किसानों से कोई संपर्क नहीं रखती थी और संपूर्ण गाँव के मुखिया 'जमींदार' को स्थायी भू-स्वामी मानती थी।\nकथन-2: व्यपगत सिद्धांत (विलय वर्ष) के अंतर्गत 'जैतपुर व संबलपुर विलय' का ऐतिहासिक संबंध '1853 ई.' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) रैयतवाड़ी में बीच में कोई जमींदार नहीं था—सीधे प्रत्येक 'रैयत' (किसान) को पट्टा दिया जाता था, हालांकि ऊँचे कर के कारण महाजनों का चंगुल बढ़ा। (2) 'जैतपुर व संबलपुर विलय' का सही संबंध '1849 ई.' से था — बुंदेलखंड के जैतपुर और ओडिशा के संबलपुर का 1849 ई. में व्यपगत सिद्धांत से विलय हुआ।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. गवर्नर-जनरल / वायसराय एवं कार्य के अंतर्गत 'लॉर्ड डलहौजी (1848-56)' का ऐतिहासिक संबंध '1858 में क्राउन शासन की घोषणा, व्यपगत नीति वापसी एवं 1861 का उच्च न्यायालय अधिनियम' से था।\n2. मारवाड़ी व गुजराती साहूकारों की ऋण बहियाँ जलाए जाने के बाद 1879 का राहत कानून बना।\n3. राजाराम मोहन राय के सहयोग से लॉर्ड विलियम बेंटिंक ने 1829 में सती प्रथा अवैध घोषित की।\n4. 1809 की अमृतसर की संधि द्वारा रणजीत सिंह के राज्य की पूर्वी सीमा सतलज नदी निर्धारित हुई।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":0,"explanation":"कथन 1 असत्य है। सुधार: 'लॉर्ड डलहौजी (1848-56)' का सही संबंध 'व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854)' से था — लॉर्ड डलहौजी ने 1854 में डाकघर अधिनियम, भारतीय रेल (1853) व सिविल सेवा की खुली प्रतियोगिता लागू की।"},
  {"q":"[PSC/CDS युग्म पहचान — प्रमुख संधियाँ एवं समझौते] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. बसीन की संधि (1802 ई.) : पेशवा बाजीराव द्वितीय द्वारा अंग्रेजों की सहायक संधि स्वीकार करना\n2. सालबाई की संधि (1782 ई.) : प्रथम आंग्ल-फ्रांसीसी कर्नाटक युद्ध का अंत व मद्रास की अंग्रेजों को वापसी\n3. एक्स-ला-शैपल की संधि (1748 ई.) : आंग्ल-नेपाल (गोरखा) युद्ध की समाप्ति (गढ़वाल, कुमाऊँ व तराई ब्रिटिश भारत को मिले)\n4. सुगौली की संधि (1816 ई.) : दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: 1802 की बसीन संधि के अंतर्गत पेशवा बाजीराव द्वितीय ने कंपनी की सहायक सेना व पूना में ब्रिटिश संरक्षण स्वीकार किया। (अन्य सही युग्म: सालबाई की संधि (1782 ई.)→प्रथम आंग्ल-मराठा युद्ध की समाप्ति (माधवराव नारायण को पेशवा स्वीकृति), एक्स-ला-शैपल की संधि (1748 ई.)→प्रथम आंग्ल-फ्रांसीसी कर्नाटक युद्ध का अंत व मद्रास की अंग्रेजों को वापसी, सुगौली की संधि (1816 ई.)→आंग्ल-नेपाल (गोरखा) युद्ध की समाप्ति (गढ़वाल, कुमाऊँ व तराई ब्रिटिश भारत को मिले))।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. लखनऊ (अवध)   B. भारत में प्रेस का विकास, प्रमुख पत्र-पत्रिकाएँ व दमनकारी एक्ट\nC. औपनिवेशिक भारत में अनौद्योगीकरण, रेलवे व बागान उद्योग   D. उदंत मार्तंड (1826, प्रथम हिंदी पत्र)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["भारत में प्रेस का विकास, प्रमुख पत्र-पत्रिकाएँ व दमनकारी एक्ट","लखनऊ (अवध)","औपनिवेशिक भारत में अनौद्योगीकरण, रेलवे व बागान उद्योग","उदंत मार्तंड (1826, प्रथम हिंदी पत्र)"],"correct":2,"explanation":"उदंत मार्तंड (1826, प्रथम हिंदी पत्र) (1826 ई.), लखनऊ (अवध) (1857 ई.), भारत में प्रेस का विकास, प्रमुख पत्र-पत्रिकाएँ व दमनकारी एक्ट (1878 ई.), औपनिवेशिक भारत में अनौद्योगीकरण, रेलवे व बागान उद्योग (1907 ई.)। अतः सबसे अंत में औपनिवेशिक भारत में अनौद्योगीकरण, रेलवे व बागान उद्योग।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. लॉर्ड विलियम बेंटिंक (1828-35) : सती प्रथा निषेध (1829), ठगी दमन व अंग्रेजी शिक्षा पर मैकाले प्रस्ताव (1835)\n2. लॉर्ड कॉर्नवालिस (1786-93) : बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना\n3. लॉर्ड लिनलिथगो (1936-44) : प्रांतीय चुनाव (1937), द्वितीय विश्व युद्ध प्रवेश (1939), अगस्त प्रस्ताव (1940) व क्रिप्स मिशन\n4. लॉर्ड डलहौजी (1848-56) : बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":3,"explanation":"युग्म 4 गलत है: 'लॉर्ड डलहौजी (1848-56)' का सही संबंध 'व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854)' से है (न कि 'बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन' से)। लॉर्ड डलहौजी ने 1854 में डाकघर अधिनियम, भारतीय रेल (1853) व सिविल सेवा की खुली प्रतियोगिता लागू की।"},
  {"q":"[UPSC Prelims पैटर्न — प्रमुख संधियाँ एवं समझौते] निम्नलिखित युग्मों पर विचार कीजिए:\n1. सुगौली की संधि (1816 ई.) : आंग्ल-नेपाल (गोरखा) युद्ध की समाप्ति (गढ़वाल, कुमाऊँ व तराई ब्रिटिश भारत को मिले)\n2. बसीन की संधि (1802 ई.) : पेशवा बाजीराव द्वितीय द्वारा अंग्रेजों की सहायक संधि स्वीकार करना\n3. मद्रास की संधि (1769 ई.) : प्रथम आंग्ल-मराठा युद्ध की समाप्ति (माधवराव नारायण को पेशवा स्वीकृति)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (लॉर्ड हेस्टिंग्स के काल में 1814-16 के आंग्ल-नेपाल युद्ध का अंत मार्च 1816 की सुगौली संधि से हुआ।) युग्म 2 सही (1802 की बसीन संधि के अंतर्गत पेशवा बाजीराव द्वितीय ने कंपनी की सहायक सेना व पूना में ब्रिटिश संरक्षण स्वीकार किया।) युग्म 3 गलत (सही: मद्रास की संधि (1769 ई.) — प्रथम आंग्ल-मैसूर युद्ध की समाप्ति (विजित क्षेत्रों की वापसी व पारस्परिक रक्षा समझौता))।"},
  {"q":"[UPSC Prelims पैटर्न — प्रमुख संधियाँ एवं समझौते] निम्नलिखित युग्मों पर विचार कीजिए:\n1. सुगौली की संधि (1816 ई.) : द्वितीय आंग्ल-मैसूर युद्ध का अंत (टीपू सुल्तान व लॉर्ड मैकार्टनी के बीच)\n2. मंगलौर की संधि (1784 ई.) : दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147)\n3. पूना समझौता / पूना पैक्ट (1932 ई.) : महाराजा रणजीत सिंह और लॉर्ड मिंटो प्रथम (चार्ल्स मेटकाफ) — सतलज नदी सीमा तय\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: सुगौली की संधि (1816 ई.) — आंग्ल-नेपाल (गोरखा) युद्ध की समाप्ति (गढ़वाल, कुमाऊँ व तराई ब्रिटिश भारत को मिले))। युग्म 2 गलत (सही: मंगलौर की संधि (1784 ई.) — द्वितीय आंग्ल-मैसूर युद्ध का अंत (टीपू सुल्तान व लॉर्ड मैकार्टनी के बीच))। युग्म 3 गलत (सही: पूना समझौता / पूना पैक्ट (1932 ई.) — दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147))।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. 19वीं सदी का वहाबी आंदोलन मुख्यतः बंबई के पारसी व्यापारियों द्वारा अंग्रेजी शिक्षा के प्रचार हेतु चलाया गया था।\n2. 1882 के हंटर शिक्षा आयोग ने केवल उच्च विश्वविद्यालयी शिक्षा और इंजीनियरिंग कॉलेजों के राष्ट्रीयकरण पर अपनी सिफारिशें दी थीं।\n3. सुधार संगठन एवं संस्थापक के अंतर्गत 'SNDP योगम (1903)' का ऐतिहासिक संबंध 'राजा राममोहन राय' से था।\n4. लॉर्ड हेस्टिंग्स के काल में 1814-16 के आंग्ल-नेपाल युद्ध का अंत मार्च 1816 की सुगौली संधि से हुआ।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (लॉर्ड हेस्टिंग्स के काल में 1814-16 के आंग्ल-नेपाल युद्ध का अंत मार्च 1816 की सुगौली संधि से हुआ।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: दादाभाई नौरोजी ने भारत की प्रति व्यक्ति वार्षिक आय मात्र 20 रुपये आंकलित करते हुए सिद्ध किया कि भारत की गरीबी प्राकृतिक नहीं बल्कि ब्रिटिश आर्थिक निष्कासन ('अनिष्टों का अनिष्ट') का परिणाम है।\nकथन-2: अप्पा साहेब के बाद दत्तक पुत्र को अमान्य कर 1848 में सर्वप्रथम सतारा का ब्रिटिश विलय हुआ।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) दादाभाई नौरोजी ने भारत की प्रति व्यक्ति वार्षिक आय मात्र 20 रुपये आंकलित करते हुए सिद्ध किया कि भारत की गरीबी प्राकृतिक नहीं बल्कि ब्रिटिश आर्थिक निष्कासन ('अनिष्टों का अनिष्ट') का परिणाम है। (2) अप्पा साहेब के बाद दत्तक पुत्र को अमान्य कर 1848 में सर्वप्रथम सतारा का ब्रिटिश विलय हुआ।"},
  {"q":"[UPSC Prelims पैटर्न — प्रमुख संधियाँ एवं समझौते] निम्नलिखित युग्मों पर विचार कीजिए:\n1. यांडबू की संधि (1826 ई.) : प्रथम आंग्ल-बर्मा युद्ध का अंत (असम, मणिपुर व अराकान-तेनासेरिम से बर्मा का दावा समाप्त)\n2. पेरिस की संधि (1763 ई.) : तृतीय आंग्ल-फ्रांसीसी कर्नाटक युद्ध की समाप्ति व भारत में फ्रांसीसी राजनीतिक शक्ति का अंत\n3. बसीन की संधि (1802 ई.) : पेशवा बाजीराव द्वितीय द्वारा अंग्रेजों की सहायक संधि स्वीकार करना\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (लॉर्ड एमहर्स्ट के शासन में 1824-26 का प्रथम आंग्ल-बर्मा युद्ध 1826 की यांडबू संधि से समाप्त हुआ।) युग्म 2 सही (1763 की पेरिस संधि से फ्रांसीसियों को केवल व्यापारिक बस्तियाँ (पांडिचेरी, चंद्रनगर) मिलीं, किलेबंदी समाप्त हुई।) युग्म 3 सही (1802 की बसीन संधि के अंतर्गत पेशवा बाजीराव द्वितीय ने कंपनी की सहायक सेना व पूना में ब्रिटिश संरक्षण स्वीकार किया।)।"},
  {"q":"[UPSC Prelims पैटर्न — प्रमुख संधियाँ एवं समझौते] निम्नलिखित युग्मों पर विचार कीजिए:\n1. बसीन की संधि (1802 ई.) : पेशवा बाजीराव द्वितीय द्वारा अंग्रेजों की सहायक संधि स्वीकार करना\n2. अमृतसर की संधि (1809 ई.) : महाराजा रणजीत सिंह और लॉर्ड मिंटो प्रथम (चार्ल्स मेटकाफ) — सतलज नदी सीमा तय\n3. इलाहाबाद की संधियाँ (1765 ई.) : ईस्ट इंडिया कंपनी को बंगाल, बिहार और उड़ीसा की दीवानी अधिकार प्राप्ति\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (1802 की बसीन संधि के अंतर्गत पेशवा बाजीराव द्वितीय ने कंपनी की सहायक सेना व पूना में ब्रिटिश संरक्षण स्वीकार किया।) युग्म 2 सही (1809 की अमृतसर की संधि द्वारा रणजीत सिंह के राज्य की पूर्वी सीमा सतलज नदी निर्धारित हुई।) युग्म 3 सही (बक्सर युद्ध के बाद इलाहाबाद की संधि से मुगल सम्राट ने कंपनी को बंगाल-बिहार-उड़ीसा की दीवानी दी।)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. 1717 के शाही फरमान द्वारा मिले 'दस्तक' पास का कंपनी के कर्मचारियों द्वारा निजी व्यापार में भारी दुरुपयोग ही बंगाल के नवाबों (सिराजुद्दौला व मीर कासिम) से संघर्ष का मूल कारण बना।\n2. गोपाल कृष्ण गोखले ने निस्वार्थ देशसेवकों के प्रशिक्षण हेतु 1905 में यह संस्था बनाई।\n3. प्रमुख संधियाँ एवं समझौते के अंतर्गत 'यांडबू की संधि (1826 ई.)' का ऐतिहासिक संबंध 'महाराजा रणजीत सिंह और लॉर्ड मिंटो प्रथम (चार्ल्स मेटकाफ) — सतलज नदी सीमा तय' से था।\n4. 1858 के भारत शासन अधिनियम व महारानी की घोषणा के अंतर्गत 'व्यपगत सिद्धांत' समाप्त किया गया, देसी रियासतों के विलय पर रोक लगी और वायसराय पद बना (प्रथम: लॉर्ड कैनिंग)।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: 'यांडबू की संधि (1826 ई.)' का सही संबंध 'प्रथम आंग्ल-बर्मा युद्ध का अंत (असम, मणिपुर व अराकान-तेनासेरिम से बर्मा का दावा समाप्त)' से था — लॉर्ड एमहर्स्ट के शासन में 1824-26 का प्रथम आंग्ल-बर्मा युद्ध 1826 की यांडबू संधि से समाप्त हुआ।"},
  {"q":"[UPSC / CDS कालानुक्रम] निम्नलिखित ऐतिहासिक घटनाओं का प्राचीनतम से नवीनतम सही कालानुक्रम क्या है?\n1. प्रार्थना समाज (1867)   2. बसीन की संधि (1802 ई.)\n3. इलाहाबाद की संधियाँ (1765 ई.)   4. नागपुर विलय","options":["इलाहाबाद की संधियाँ (1765 ई.) → बसीन की संधि (1802 ई.) → प्रार्थना समाज (1867) → नागपुर विलय","इलाहाबाद की संधियाँ (1765 ई.) → बसीन की संधि (1802 ई.) → नागपुर विलय → प्रार्थना समाज (1867)","इलाहाबाद की संधियाँ (1765 ई.) → नागपुर विलय → बसीन की संधि (1802 ई.) → प्रार्थना समाज (1867)","बसीन की संधि (1802 ई.) → इलाहाबाद की संधियाँ (1765 ई.) → नागपुर विलय → प्रार्थना समाज (1867)"],"correct":1,"explanation":"सही कालानुक्रम: इलाहाबाद की संधियाँ (1765 ई.) (1765 ई.), बसीन की संधि (1802 ई.) (1802 ई.), नागपुर विलय (1854 ई.), प्रार्थना समाज (1867) (1867 ई.)"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: धन के निष्कासन सिद्धांत के अंतर्गत दादाभाई नौरोजी ने ब्रिटिश रेलवे गारंटी प्रणाली और मुक्त व्यापार को भारत के औद्योगीकरण का सबसे बड़ा वरदान बताया।\nकथन-2: 1854 के चार्ल्स वुड के डिस्पैच ने 'अधोगामी निस्यंदन सिद्धांत' (Downward Filtration) को त्याग कर जनसाधारण व महिला शिक्षा, प्राथमिक मातृभाषा व 1857 में कलकत्ता-बंबई-मद्रास विश्वविद्यालय स्थापना की राह खोली।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है (नौरोजी, दत्त व तिलक जैसे आर्थिक राष्ट्रवादियों ने स्पष्ट किया कि भारत में रेलवे गारंटी प्रणाली, अनिर्यात योग्य 'होम चार्जेज' व एकतरफा मुक्त व्यापार ने भारतीय हस्तशिल्प (अनौद्योगीकरण) को नष्ट किया।)। कथन-2 सत्य है (1854 के चार्ल्स वुड के डिस्पैच ने 'अधोगामी निस्यंदन सिद्धांत' (Downward Filtration) को त्याग कर जनसाधारण व महिला शिक्षा, प्राथमिक मातृभाषा व 1857 में कलकत्ता-बंबई-मद्रास विश्वविद्यालय स्थापना की राह खोली।)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: डब्ल्यू.डब्ल्यू. हंटर की अध्यक्षता वाले आयोग ने प्राथमिक शिक्षा को स्थानीय निकायों (जिला-नगर बोर्ड) को सौंपने पर बल दिया।\nकथन-2: 1809 की अमृतसर की संधि द्वारा रणजीत सिंह के राज्य की पूर्वी सीमा सतलज नदी निर्धारित हुई।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) डब्ल्यू.डब्ल्यू. हंटर की अध्यक्षता वाले आयोग ने प्राथमिक शिक्षा को स्थानीय निकायों (जिला-नगर बोर्ड) को सौंपने पर बल दिया। (2) 1809 की अमृतसर की संधि द्वारा रणजीत सिंह के राज्य की पूर्वी सीमा सतलज नदी निर्धारित हुई।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. सर जॉन लॉरेंस ने 'फॉरवर्ड पॉलिसी' के तहत 1904 में तिब्बत की राजधानी ल्हासा पर यंगहसबैंड सैन्य अभियान भेजा था।\n2. पुर्तगाली गवर्नर नीनो डी कुन्हा ने 1510 ई. में कालीकट में पहली फैक्ट्री खोलकर 'ब्लू वाटर पॉलिसी' प्रारंभ की थी।\n3. 1857 क्रांति केंद्र एवं नेता के अंतर्गत 'लखनऊ (अवध)' का ऐतिहासिक संबंध 'नाना साहेब एवं तात्या टोपे' से था।\n4. लॉर्ड डलहौजी ने 1854 में डाकघर अधिनियम, भारतीय रेल (1853) व सिविल सेवा की खुली प्रतियोगिता लागू की।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (लॉर्ड डलहौजी ने 1854 में डाकघर अधिनियम, भारतीय रेल (1853) व सिविल सेवा की खुली प्रतियोगिता लागू की।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: प्रमुख संधियाँ एवं समझौते के अंतर्गत 'यांडबू की संधि (1826 ई.)' का ऐतिहासिक संबंध 'महाराजा रणजीत सिंह और लॉर्ड मिंटो प्रथम (चार्ल्स मेटकाफ) — सतलज नदी सीमा तय' से था।\nकथन-2: 1717 के शाही फरमान द्वारा मिले 'दस्तक' पास का कंपनी के कर्मचारियों द्वारा निजी व्यापार में भारी दुरुपयोग ही बंगाल के नवाबों (सिराजुद्दौला व मीर कासिम) से संघर्ष का मूल कारण बना।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है ('यांडबू की संधि (1826 ई.)' का सही संबंध 'प्रथम आंग्ल-बर्मा युद्ध का अंत (असम, मणिपुर व अराकान-तेनासेरिम से बर्मा का दावा समाप्त)' से था — लॉर्ड एमहर्स्ट के शासन में 1824-26 का प्रथम आंग्ल-बर्मा युद्ध 1826 की यांडबू संधि से समाप्त हुआ।)। कथन-2 सत्य है (1717 के शाही फरमान द्वारा मिले 'दस्तक' पास का कंपनी के कर्मचारियों द्वारा निजी व्यापार में भारी दुरुपयोग ही बंगाल के नवाबों (सिराजुद्दौला व मीर कासिम) से संघर्ष का मूल कारण बना।)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. सुगौली की संधि (1816 ई.)   B. आधुनिक शिक्षा का विकास: मैकाले से सार्जेंट योजना तक\nC. स्थायी बंदोबस्त (इस्तमरारी / जमींदारी व्यवस्था, 1793)   D. अमृत बाजार पत्रिका (1868)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["स्थायी बंदोबस्त (इस्तमरारी / जमींदारी व्यवस्था, 1793)","अमृत बाजार पत्रिका (1868)","आधुनिक शिक्षा का विकास: मैकाले से सार्जेंट योजना तक","सुगौली की संधि (1816 ई.)"],"correct":0,"explanation":"स्थायी बंदोबस्त (इस्तमरारी / जमींदारी व्यवस्था, 1793) (1793 ई.), सुगौली की संधि (1816 ई.) (1816 ई.), आधुनिक शिक्षा का विकास: मैकाले से सार्जेंट योजना तक (1854 ई.), अमृत बाजार पत्रिका (1868) (1868 ई.)। अतः सर्वप्रथम स्थायी बंदोबस्त (इस्तमरारी / जमींदारी व्यवस्था, 1793)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: महालवाड़ी व्यवस्था का व्यावहारिक रूप से उत्तर भारत में व्यवस्थित कार्यान्वयन 1833 में लॉर्ड विलियम बेंटिंक के समय मार्टिन बर्ड ('उत्तर भारत में भू-राजस्व का जनक') व जेम्स थॉमसन ने किया।\nकथन-2: स्थायी बंदोबस्त में राज्य की माँग स्थायी रूप से तय कर दी गई थी, किंतु जमींदारों और रैयतों (किसानों) के बीच लगान की कोई अधिकतम सीमा तय नहीं थी, जिससे 'पट्टनीदार' मध्यस्थ बढ़े।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) महालवाड़ी व्यवस्था का व्यावहारिक रूप से उत्तर भारत में व्यवस्थित कार्यान्वयन 1833 में लॉर्ड विलियम बेंटिंक के समय मार्टिन बर्ड ('उत्तर भारत में भू-राजस्व का जनक') व जेम्स थॉमसन ने किया। (2) स्थायी बंदोबस्त में राज्य की माँग स्थायी रूप से तय कर दी गई थी, किंतु जमींदारों और रैयतों (किसानों) के बीच लगान की कोई अधिकतम सीमा तय नहीं थी, जिससे 'पट्टनीदार' मध्यस्थ बढ़े।"},
  {"q":"31 दिसंबर 1802 की 'बसीन (वसई) की संधि' किस मराठा पेशवा ने लॉर्ड वेलेजली के साथ की थी?","options":["पेशवा बाजीराव द्वितीय द्वारा अंग्रेजों की सहायक संधि स्वीकार करना","ईस्ट इंडिया कंपनी को बंगाल, बिहार और उड़ीसा की दीवानी अधिकार प्राप्ति","तृतीय आंग्ल-फ्रांसीसी कर्नाटक युद्ध की समाप्ति व भारत में फ्रांसीसी राजनीतिक शक्ति का अंत","प्रथम आंग्ल-फ्रांसीसी कर्नाटक युद्ध का अंत व मद्रास की अंग्रेजों को वापसी"],"correct":0,"explanation":"1802 की बसीन संधि के अंतर्गत पेशवा बाजीराव द्वितीय ने कंपनी की सहायक सेना व पूना में ब्रिटिश संरक्षण स्वीकार किया। इतिहासकार सिडनी ओवेन ने कहा कि बसीन की संधि ने अंग्रेजों को भारत का साम्राज्य सौंप दिया।"},
  {"q":"1826 ई. की 'यांडबू की संधि' किस युद्ध की समाप्ति के साथ संपन्न हुई?","options":["ईस्ट इंडिया कंपनी को बंगाल, बिहार और उड़ीसा की दीवानी अधिकार प्राप्ति","प्रथम आंग्ल-बर्मा युद्ध का अंत (असम, मणिपुर व अराकान-तेनासेरिम से बर्मा का दावा समाप्त)","तृतीय आंग्ल-फ्रांसीसी कर्नाटक युद्ध की समाप्ति व भारत में फ्रांसीसी राजनीतिक शक्ति का अंत","प्रथम आंग्ल-फ्रांसीसी कर्नाटक युद्ध का अंत व मद्रास की अंग्रेजों को वापसी"],"correct":1,"explanation":"लॉर्ड एमहर्स्ट के शासन में 1824-26 का प्रथम आंग्ल-बर्मा युद्ध 1826 की यांडबू संधि से समाप्त हुआ। बाद में लॉर्ड डफरिन के समय 1885 में तृतीय युद्ध द्वारा ऊपरी बर्मा का पूर्ण विलय हुआ।"},
  {"q":"[UPSC/PCS सूची सुमेलन — प्रमुख संधियाँ एवं समझौते] सूची-I को सूची-II से सुमेलित कीजिए:\nA. अमृतसर की संधि (1809 ई.)   |   1. प्रथम आंग्ल-मराठा युद्ध की समाप्ति (माधवराव नारायण को पेशवा स्वीकृति)\nB. मंगलौर की संधि (1784 ई.)   |   2. तृतीय आंग्ल-फ्रांसीसी कर्नाटक युद्ध की समाप्ति व भारत में फ्रांसीसी राजनीतिक शक्ति का अंत\nC. पेरिस की संधि (1763 ई.)   |   3. महाराजा रणजीत सिंह और लॉर्ड मिंटो प्रथम (चार्ल्स मेटकाफ) — सतलज नदी सीमा तय\nD. सालबाई की संधि (1782 ई.)   |   4. द्वितीय आंग्ल-मैसूर युद्ध का अंत (टीपू सुल्तान व लॉर्ड मैकार्टनी के बीच)","options":["A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2","A-3, B-2, C-4, D-1","A-4, B-3, C-2, D-1"],"correct":0,"explanation":"सही सुमेलन: अमृतसर की संधि (1809 ई.) (महाराजा रणजीत सिंह और लॉर्ड मिंटो प्रथम (चार्ल्स मेटकाफ) — सतलज नदी सीमा तय), मंगलौर की संधि (1784 ई.) (द्वितीय आंग्ल-मैसूर युद्ध का अंत (टीपू सुल्तान व लॉर्ड मैकार्टनी के बीच)), पेरिस की संधि (1763 ई.) (तृतीय आंग्ल-फ्रांसीसी कर्नाटक युद्ध की समाप्ति व भारत में फ्रांसीसी राजनीतिक शक्ति का अंत), सालबाई की संधि (1782 ई.) (प्रथम आंग्ल-मराठा युद्ध की समाप्ति (माधवराव नारायण को पेशवा स्वीकृति))।"},
  {"q":"[UPSC Prelims पैटर्न — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित युग्मों पर विचार कीजिए:\n1. लॉर्ड डलहौजी (1848-56) : व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854)\n2. लॉर्ड कैनिंग (1856-62) : 1858 में क्राउन शासन की घोषणा, व्यपगत नीति वापसी एवं 1861 का उच्च न्यायालय अधिनियम\n3. लॉर्ड कर्जन (1899-1905) : सती प्रथा निषेध (1829), ठगी दमन व अंग्रेजी शिक्षा पर मैकाले प्रस्ताव (1835)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (लॉर्ड डलहौजी ने 1854 में डाकघर अधिनियम, भारतीय रेल (1853) व सिविल सेवा की खुली प्रतियोगिता लागू की।) युग्म 2 सही (लॉर्ड कैनिंग कंपनी के अंतिम गवर्नर-जनरल तथा 1858 के बाद भारत के प्रथम वायसराय बने।) युग्म 3 गलत (सही: लॉर्ड कर्जन (1899-1905) — बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: महालवाड़ी व्यवस्था का व्यावहारिक रूप से उत्तर भारत में व्यवस्थित कार्यान्वयन 1833 में लॉर्ड विलियम बेंटिंक के समय मार्टिन बर्ड ('उत्तर भारत में भू-राजस्व का जनक') व जेम्स थॉमसन ने किया।\nकथन-2: सहायक संधि स्वीकार करने वाला प्रथम भारतीय राज्य हैदराबाद का निजाम (1798) था; मराठा सरदारों में होलकर ने सबसे अंत में या स्वतंत्र रहने का प्रयास किया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) महालवाड़ी व्यवस्था का व्यावहारिक रूप से उत्तर भारत में व्यवस्थित कार्यान्वयन 1833 में लॉर्ड विलियम बेंटिंक के समय मार्टिन बर्ड ('उत्तर भारत में भू-राजस्व का जनक') व जेम्स थॉमसन ने किया। (2) सहायक संधि स्वीकार करने वाला प्रथम भारतीय राज्य हैदराबाद का निजाम (1798) था; मराठा सरदारों में होलकर ने सबसे अंत में या स्वतंत्र रहने का प्रयास किया।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. प्लासी का युद्ध (1757) एवं ब्लैक होल त्रासदी   B. फैजाबाद\nC. चार्ल्स मेटकाफ (1835-36)   D. धन के निष्कासन का सिद्धांत (Drain of Wealth) व आर्थिक राष्ट्रवाद\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["धन के निष्कासन का सिद्धांत (Drain of Wealth) व आर्थिक राष्ट्रवाद","प्लासी का युद्ध (1757) एवं ब्लैक होल त्रासदी","चार्ल्स मेटकाफ (1835-36)","फैजाबाद"],"correct":0,"explanation":"प्लासी का युद्ध (1757) एवं ब्लैक होल त्रासदी (1757 ई.), चार्ल्स मेटकाफ (1835-36) (1835 ई.), फैजाबाद (1857 ई.), धन के निष्कासन का सिद्धांत (Drain of Wealth) व आर्थिक राष्ट्रवाद (1867 ई.)। अतः सबसे अंत में धन के निष्कासन का सिद्धांत (Drain of Wealth) व आर्थिक राष्ट्रवाद।"},
  {"q":"[PSC/CDS युग्म पहचान — प्रमुख संधियाँ एवं समझौते] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. गांधी-इरविन समझौता (1931 ई.) : पेशवा बाजीराव द्वितीय द्वारा अंग्रेजों की सहायक संधि स्वीकार करना\n2. बसीन की संधि (1802 ई.) : प्रथम आंग्ल-बर्मा युद्ध का अंत (असम, मणिपुर व अराकान-तेनासेरिम से बर्मा का दावा समाप्त)\n3. यांडबू की संधि (1826 ई.) : दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147)\n4. अमृतसर की संधि (1809 ई.) : महाराजा रणजीत सिंह और लॉर्ड मिंटो प्रथम (चार्ल्स मेटकाफ) — सतलज नदी सीमा तय","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: 1809 की अमृतसर की संधि द्वारा रणजीत सिंह के राज्य की पूर्वी सीमा सतलज नदी निर्धारित हुई। (अन्य सही युग्म: गांधी-इरविन समझौता (1931 ई.)→सविनय अवज्ञा आंदोलन का स्थगन और कांग्रेस की द्वितीय गोलमेज सम्मेलन में भागीदारी, बसीन की संधि (1802 ई.)→पेशवा बाजीराव द्वितीय द्वारा अंग्रेजों की सहायक संधि स्वीकार करना, यांडबू की संधि (1826 ई.)→प्रथम आंग्ल-बर्मा युद्ध का अंत (असम, मणिपुर व अराकान-तेनासेरिम से बर्मा का दावा समाप्त))।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. देवबंद आंदोलन (1866) ने भारतीय राष्ट्रीय कांग्रेस के विरुद्ध सर सैय्यद अहमद खाँ का पूर्ण समर्थन किया और केवल अंग्रेजी शिक्षा पर जोर दिया।\n2. 1802 की बसीन संधि के अंतर्गत पेशवा बाजीराव द्वितीय ने कंपनी की सहायक सेना व पूना में ब्रिटिश संरक्षण स्वीकार किया।\n3. पत्र-पत्रिकाएँ एवं संपादक के अंतर्गत 'हिंदू पैट्रियट (नील विद्रोह समर्थक)' का ऐतिहासिक संबंध 'सुरेंद्रनाथ बनर्जी' से था।\n4. वर्नाक्यूलर प्रेस एक्ट (1878) लॉर्ड रिपन द्वारा लागू किया गया था तथा लॉर्ड लिटन ने 1882 में इसे समाप्त कर प्रेस को पूर्ण स्वतंत्रता दी।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":1,"explanation":"कथन 2 सत्य है (1802 की बसीन संधि के अंतर्गत पेशवा बाजीराव द्वितीय ने कंपनी की सहायक सेना व पूना में ब्रिटिश संरक्षण स्वीकार किया।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — प्रमुख संधियाँ एवं समझौते] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. अमृतसर की संधि (1809 ई.) : पेशवा बाजीराव द्वितीय द्वारा अंग्रेजों की सहायक संधि स्वीकार करना\n2. सुगौली की संधि (1816 ई.) : आंग्ल-नेपाल (गोरखा) युद्ध की समाप्ति (गढ़वाल, कुमाऊँ व तराई ब्रिटिश भारत को मिले)\n3. इलाहाबाद की संधियाँ (1765 ई.) : ईस्ट इंडिया कंपनी को बंगाल, बिहार और उड़ीसा की दीवानी अधिकार प्राप्ति\n4. गांधी-इरविन समझौता (1931 ई.) : सविनय अवज्ञा आंदोलन का स्थगन और कांग्रेस की द्वितीय गोलमेज सम्मेलन में भागीदारी","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":0,"explanation":"युग्म 1 गलत है: 'अमृतसर की संधि (1809 ई.)' का सही संबंध 'महाराजा रणजीत सिंह और लॉर्ड मिंटो प्रथम (चार्ल्स मेटकाफ) — सतलज नदी सीमा तय' से है (न कि 'पेशवा बाजीराव द्वितीय द्वारा अंग्रेजों की सहायक संधि स्वीकार करना' से)। 1809 की अमृतसर की संधि द्वारा रणजीत सिंह के राज्य की पूर्वी सीमा सतलज नदी निर्धारित हुई।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. झाँसी विलय (गंगाधर राव मृत्यु बाद)   B. हिंदू पैट्रियट (नील विद्रोह समर्थक)\nC. भारत में प्रेस का विकास, प्रमुख पत्र-पत्रिकाएँ व दमनकारी एक्ट   D. बसीन की संधि (1802 ई.)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["हिंदू पैट्रियट (नील विद्रोह समर्थक)","बसीन की संधि (1802 ई.)","भारत में प्रेस का विकास, प्रमुख पत्र-पत्रिकाएँ व दमनकारी एक्ट","झाँसी विलय (गंगाधर राव मृत्यु बाद)"],"correct":1,"explanation":"बसीन की संधि (1802 ई.) (1802 ई.), झाँसी विलय (गंगाधर राव मृत्यु बाद) (1853 ई.), हिंदू पैट्रियट (नील विद्रोह समर्थक) (1859 ई.), भारत में प्रेस का विकास, प्रमुख पत्र-पत्रिकाएँ व दमनकारी एक्ट (1878 ई.)। अतः सर्वप्रथम बसीन की संधि (1802 ई.)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. स्वामी विवेकानंद ने अपने गुरु रामकृष्ण परमहंस की शिक्षाओं व मानव सेवा हेतु रामकृष्ण मिशन की नींव रखी।\n2. लॉर्ड हेस्टिंग्स के काल में 1814-16 के आंग्ल-नेपाल युद्ध का अंत मार्च 1816 की सुगौली संधि से हुआ।\n3. स्थायी बंदोबस्त लॉर्ड डलहौजी द्वारा 1820 ई. में मद्रास और बंबई प्रेसीडेंसी के 51% ब्रिटिश भारतीय क्षेत्र में लागू किया गया था।\n4. पूर्व ब्रह्म समाजी शिव नारायण अग्निहोत्री ने 1887 में लाहौर में देव समाज की स्थापना की।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: स्थायी बंदोबस्त 1793 में लॉर्ड कॉर्नवालिस ने मुख्यतः बंगाल-बिहार-ओडिशा (~19% ब्रिटिश भूमि) में लागू किया था; मद्रास-बंबई (51%) में रैयतवाड़ी लागू हुई।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. झाँसी विलय (गंगाधर राव मृत्यु बाद)   B. नागपुर विलय\nC. चार्टर अधिनियम, 1833   D. बसीन की संधि (1802 ई.)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["बसीन की संधि (1802 ई.)","चार्टर अधिनियम, 1833","झाँसी विलय (गंगाधर राव मृत्यु बाद)","नागपुर विलय"],"correct":0,"explanation":"बसीन की संधि (1802 ई.) (1802 ई.), चार्टर अधिनियम, 1833 (1833 ई.), झाँसी विलय (गंगाधर राव मृत्यु बाद) (1853 ई.), नागपुर विलय (1854 ई.)। अतः सर्वप्रथम बसीन की संधि (1802 ई.)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: प्रमुख संधियाँ एवं समझौते के अंतर्गत 'इलाहाबाद की संधियाँ (1765 ई.)' का ऐतिहासिक संबंध 'प्रथम आंग्ल-मैसूर युद्ध की समाप्ति (विजित क्षेत्रों की वापसी व पारस्परिक रक्षा समझौता)' से था।\nकथन-2: प्रमुख संधियाँ एवं समझौते के अंतर्गत 'बसीन की संधि (1802 ई.)' का ऐतिहासिक संबंध 'आंग्ल-नेपाल (गोरखा) युद्ध की समाप्ति (गढ़वाल, कुमाऊँ व तराई ब्रिटिश भारत को मिले)' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'इलाहाबाद की संधियाँ (1765 ई.)' का सही संबंध 'ईस्ट इंडिया कंपनी को बंगाल, बिहार और उड़ीसा की दीवानी अधिकार प्राप्ति' से था — बक्सर युद्ध के बाद इलाहाबाद की संधि से मुगल सम्राट ने कंपनी को बंगाल-बिहार-उड़ीसा की दीवानी दी। (2) 'बसीन की संधि (1802 ई.)' का सही संबंध 'पेशवा बाजीराव द्वितीय द्वारा अंग्रेजों की सहायक संधि स्वीकार करना' से था — 1802 की बसीन संधि के अंतर्गत पेशवा बाजीराव द्वितीय ने कंपनी की सहायक सेना व पूना में ब्रिटिश संरक्षण स्वीकार किया।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: गवर्नर-जनरल / वायसराय एवं कार्य के अंतर्गत 'लॉर्ड डलहौजी (1848-56)' का ऐतिहासिक संबंध '1858 में क्राउन शासन की घोषणा, व्यपगत नीति वापसी एवं 1861 का उच्च न्यायालय अधिनियम' से था।\nकथन-2: सर जॉन लॉरेंस ने 'फॉरवर्ड पॉलिसी' के तहत 1904 में तिब्बत की राजधानी ल्हासा पर यंगहसबैंड सैन्य अभियान भेजा था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'लॉर्ड डलहौजी (1848-56)' का सही संबंध 'व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854)' से था — लॉर्ड डलहौजी ने 1854 में डाकघर अधिनियम, भारतीय रेल (1853) व सिविल सेवा की खुली प्रतियोगिता लागू की। (2) 1904 में तिब्बत का यंगहसबैंड अभियान लॉर्ड कर्जन ने भेजा था (ल्हासा संधि); लॉरेंस अफ़गान मामलों में 'कुशल अकर्मण्यता' नीति के जनक थे।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. ब्रिटिश भारत की विदेश एवं सीमांत नीति (घेरे की नीति व अग्रगामी नीति)   B. जैतपुर व संबलपुर विलय\nC. कोल विद्रोह (1831-32)   D. सुगौली की संधि (1816 ई.)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["जैतपुर व संबलपुर विलय","सुगौली की संधि (1816 ई.)","ब्रिटिश भारत की विदेश एवं सीमांत नीति (घेरे की नीति व अग्रगामी नीति)","कोल विद्रोह (1831-32)"],"correct":1,"explanation":"सुगौली की संधि (1816 ई.) (1816 ई.), कोल विद्रोह (1831-32) (1831-32 ई.), ब्रिटिश भारत की विदेश एवं सीमांत नीति (घेरे की नीति व अग्रगामी नीति) (1839-42 ई.), जैतपुर व संबलपुर विलय (1849 ई.)। अतः सर्वप्रथम सुगौली की संधि (1816 ई.)।"}
]);
